quests[11113] = { id = 11113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voranaku the Violet Netherwing Drake", sourceObjective = "It is an honor to meet you, {name}. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11114] = { id = 11114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zoya the Veridian Netherwing Drake", sourceObjective = "It is an honor to meet you, {name}. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11115] = { id = 11115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of Vashj (FLAG ONLY)" }
quests[11116] = { id = 11116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Naaru: (QUEST FLAG)", description = "Four trials you must pass before you are deemed worthy of the Tempest key.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!\n\nDo this and you will be granted the Tempest key.", sourceObjective = "A'dal in Shattrath City wants you to slay Magtheridon.", sourceObjectiveStatus = "unverified-source-field" }
quests[11117] = { id = 11117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch the Wild Wolpertinger!", description = "Here now. Ye hear that? There be sounds in them hills. Those're the wolpertingers! Wily beasts, they are, attracted by the smells o' Brewfest. I've a mind to catch me some, but I knocked me shin and can't outrun the buggers. Ye can help me, though!\n\nTake this net and cast it over the little blighters. Bring me a good five of 'em and I'll make it worth yer while! Oh, and one more thing - in order to even see these critters, ye need t' be blitzed! Load up on the booze!", sourceObjective = "Goldark Snipehunter has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. He mentioned that you must be intoxicated to see them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11118] = { id = 11118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pink Elekks On Parade", description = "Getting drunk is a time-honored tradition at Brewfest -- it's damn near required! Thing is, I'm getting reports across Azeroth saying the celebration's plagued by hallucinations!  We can't have that!\n\nThese elekks can't be harmed by normal weapons -- they pass right through 'em -- so take this fabulous piece of gnomish machinery, visit the other beer gardens, and zap 'em to oblivion. Remember, you have to be drunk to see 'em!", sourceObjective = "Visit the beer gardens outside of Stormwind, Darnassus, and the Exodar, zap three elekks at each location, and return to Goldark Snipehunter. You must be drunk to see the pink elekks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11119] = { id = 11119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Bash'ir Landing!", description = "Heya, <boyo/girly>!  Up fer some fun are ye?\n\nEvery couple o' hours, me aether-techs launch an assault on Bash'ir Landing, far ta the northeast in the Blade's Edge Mountains.  They say that they're there 'studying' the Bash'ir crystalforge, but it's an assault; there be no two ways about it.  We use the crystalforge to resupply, and there's always extra to be sold.\n\nGo on down ta the landin' pad and speak with the aether-tech apprentice.  He'll tell ye when the next mission is ta launch.", sourceObjective = "Sky Commander Keller has asked you to speak with the Aether-tech Apprentice at the Skyguard Outpost in the Blade's Edge Mountains.", completion = "Despite how Keller cares to characterize it, I prefer to think of our missions as research-oriented.\n\nBut yes, we do resupply the Skyguard while we're there.  That is if we can stay long enough to do so.\n\nYou look like you'd be willing to keep the ethereals off of our backs.  If you can manage to for long enough, we'll sell you surplus items that we create at the crystalforge, so bring your apexis shards and crystals!\n\nWe leave in 0 |4minute:minutes;.", sourceObjectiveStatus = "unverified-source-field" }
quests[11120] = { id = 11120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pink Elekks On Parade", description = "Look. We're running a business here. People being drunk? It's good business. But I'll tell ya one thing that puts a cramp in the profits - hallucinations. Wouldn't ya know it, the boys are reporting that the sot- er, the loyal customers are seeing pink elekks everywhere.\n\nI don't need my customers unsettled. Look, take this ray and travel to the other beer gardens to take care of 'em for me, would ya? And be sure to get drunk!", sourceObjective = "Visit the beer gardens outside of Silvermoon, Thunder Bluff, and the Undercity, zap three elekks at each location, and return to Glodrak Huntsniper. You must be drunk to see the pink elekks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11122] = { id = 11122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There and Back Again", description = "So you want to help out at Brewfest?  I've got the perfect task for ya.  I'll put you on one of my racing rams and you head down to Kharanos.  I've got some kegs I need to pick up.  \n\nFlynn Firebrew is waiting on a hill near a stack of kegs.  He'll toss you a keg when you get near, then you run the keg back here and toss the keg to Pol Amberstill.  You can only carry one at a time.  \n\nReady?", sourceObjective = "Get a keg from Flynn Firebrew in Kharanos and return it to Pol Amberstill. Do this 3 times before your ram goes away.", progress = "I need those kegs!  So, what are yeh waitin' for!?!", completion = "Thanks a lot for your help!  As long as Brewfest is going and the Dark Iron dwarves are attacking, I'll need some help shipping kegs.  So if you want to work for more tokens, talk to me every day.\n\nBut enough about that, I need to pay you for the job you just did.  Here are your tokens, have fun at Brewfest!", sourceObjectiveStatus = "unverified-source-field" }
quests[11123] = { id = 11123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspecting the Ruins", description = "Poor James never recovered from the destruction of the Shady Rest and the murder of his family. The boys and I are doing what we can to find the bastards who did this.\n\nI've sent our best investigator, Inspector Tarem, out to the ruins, but this is too big a job for any one man. If you'd lend Tarem a hand, we'd appreciate it. Light knows, we'd all like to be out there helping.\n\nThe main road will lead you to the inn, but take care. Your journey will take you beyond the protection of my soldiers.", sourceObjective = "Speak to Inspector Tarem at the Shady Rest Inn.", completion = "It's good to see that Captain Vimes is finally assigning others to this investigation.\n\nI've used a reflective powder to dust the area. It will reveal suspicious objects and markings, helping you to focus your efforts. Look over anything the dust illuminates.", sourceObjectiveStatus = "unverified-source-field" }
quests[11124] = { id = 11124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspecting the Ruins", description = "If you follow the road south from the village, and then west toward the Barrens, you'll come across the ruins of the Shady Rest Inn.\n\nTheramore has sent an investigator to discover how the inn met its fate. Normally, I'd advise you to steer clear, but we have orders from Orgrimmar to 'assist' in the investigation.\n\nAccept any help the Theramore investigator offers, even feed him a tidbit or two of information if you'd like, but save your real findings for me.", sourceObjective = "Speak to Inspector Tarem at the Shady Rest Inn.", completion = "<The inspector regards you with what can only be distrust.>\n\nI've been told that you're to... aid in this investigation. Very well, then.\n\nI've been using this powder to search the ruins for clues that might help identify the attackers. It will illuminate anything that might have been involved in the attack. Don't hesitate to examine anything that looks suspicious.", sourceObjectiveStatus = "unverified-source-field" }
quests[11126] = { id = 11126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors Among Us", description = "It's good to meet you, {class}. I've come to Theramore to help eliminate the problem of the deserters. Not only have some of the men abandoned their posts, but some have filtered back into the town.\n\nThese deserter agents are spreading lies and propaganda, hoping to convince others to join their ranks.\n\nThey're at virtually every guard post throughout the town and the docks. Find them, expose them, and discredit them. At this point, anything more risks inspiring more sympathy for them.", sourceObjective = "Confront 5 Deserter Agitators and return to Calia Hastings near the docks in Theramore.", progress = "Have you driven the deserter agents from Theramore?", completion = "Well done, {name}. I think we managed to catch them off guard. Their agents probably thought themselves safe within the city walls.\n\nGiven time, the agitators will return and spread their lies again. We'll use the time you've bought to shut out the deserters further.", sourceObjectiveStatus = "unverified-source-field" }
quests[11128] = { id = 11128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propaganda War", description = "The deserter agents were doing far more than just chatting up the guards. We've found a number of leaflets the deserters somehow managed to smuggle in on a ship in the docks.\n\nThe ship used to transport the leaflets is still in Theramore, at the farthest dock. If you can sneak aboard and capture the rest of their propaganda documents, their agents will lose their most powerful tool. Be careful! The ship is manned by seasoned privateers and the cargo is probably being kept in the captain's quarters.", sourceObjective = "Bring the Deserter Propaganda to Calia Hastings near the docks in Theramore.", progress = "Did you manage to find and capture the remaining propaganda leaflets?", completion = "<The SI:7 agent nods in approval.>\n\nExcellent. All that remains is to discredit the deserters so that they'll never gain a foothold in Theramore again, and I have just the plan to do it.", sourceObjectiveStatus = "unverified-source-field" }
quests[11129] = { id = 11129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyle's Gone Missing!", description = "Help, {name}! My prized puppy, Kyle, has run away! I just know he's running around Bloodhoof Village, lost and hungry.\n\nWill you find him and feed him? Once he eats he will settle down and come home.\n\nTo feed him you will need to find food. His favorite meal is tender strider meat. Just venture east and you should find plenty of striders. Hunt one down and take its succulent meat to Kyle. When you see Kyle in town, put the meat down and he is sure to come to you.", sourceObjective = "Ahab Wheathoof at Bloodhoof Village in Mulgore wants you to feed his prized puppy, Kyle the Frenzied.\n\nFeed Kyle Tender Strider Meat and return to Ahab Wheathoof.", progress = "Did you find Kyle?", completion = "Fantastic work, {name}! Kyle came home as soon as he ate and went straight to bed. Thank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[11130] = { id = 11130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oooh, Shinies!", description = "Come closer, <man/sweetheart>! Let ol' Griftah look at yer shiny things....\n\nHmm. Yeh, yeh, not bad, but ya can do better. Much, much better.\n\n<Griftah leans in and whispers.>\n\nThere be priceless shinies everywhere, {name}, ya just gotta know where to look! It be yer lucky day; I know a fella who can help ya find more shinies than ya can ever carry.\n\nVisit my ol' friend, Budd, near Zul'Aman and show him this here. Ya be tellin' him ol' Griftah sent ya and he'll let ya in on his new project.", sourceObjective = "Griftah wants you to take Griftah's Note to Budd in the Ghostlands, just outside of Zul'Aman.", progress = "<Budd eyes the note suspiciously.>\n\nWhat have you there, {class}?", completion = "<Budd reads the note.>\n\nAhh! A friend of Griftah? Welcome!\n\nYou have impeccable timing, friend. As fate would have it, I recently lost my latest partners. Tragic, truly, but great rewards often have a high price. Best not to dwell on the negative!\n\nYou've doubtlessly heard of my countless exploits and discoveries. Well, all of that was nothing compared to this! Truth is, we're close to making history here at Zul'Aman and, by fate's decree, you're in on the ground floor!", sourceObjectiveStatus = "unverified-source-field" }
quests[11131] = { id = 11131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Fires!", description = "You must help us!  The Headless Horseman is attacking the village.  Fires are everywhere!  The children aren't safe!\n\nPlease, {name}, join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  Put out all the fires and we may yet be saved!", sourceObjective = "The Costumed Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Costumed Orphan Matron.", progress = "{name}, you promised to save the children!", completion = "Oh, thank you!  May the Light bless your good works, kind sir.  The shadow of the Dark Horseman yet looms, but at least, for now, the village is safe from his flames.", sourceObjectiveStatus = "unverified-source-field" }
quests[11132] = { id = 11132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Promises, Promises...", description = "My inscrutable theories confirm rumors of vast treasure in Zul'Aman. There'll be mounts and mansions for everyone! First things first, though. You must earn your share, after all....\n\nOur initial efforts here haven't gone as well as I hoped. In fact, my map, and the recruits I lent it to, have gone missing. They were after a troll-beast named Nalorakk.\n\nForget the crew, I need that map! Succeed, and you'll go down in history as the one who helped Budd Nedreck unlock the secrets of Zul'Aman!", sourceObjective = "Budd Nedreck in Hatchet Hills wants you to retrieve his map from High Priest Nalorakk's terrace in Zul'Aman.", progress = "Ahh yes, {name}, isn't it?\n\nHave you recovered my map yet?", completion = "<Budd looks a bit shocked.>\n\nOh? You've found it?\n\nAhem, I mean, of course you have! Well done, {class}.\n\nLet me see if I can find you a little something nice... ahh yes, this should do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11133] = { id = 11133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discrediting the Deserters", description = "I've altered the leaflets you captured from the deserters' mercenary friends at the docks. Now, anyone who reads them will get an entirely different view of the deserters and their aims.\n\nIf we distribute these to enough of the guards, the deserters will be too embarrassed to ever reestablish their presence within our walls.\n\n<Calia hands you a stack of the altered leaflets.>\n\nWhy don't you get started while I plan our next move?", sourceObjective = "Calia Hastings wants you to distribute the Altered Leaflets to 6 Theramore Guards, then report back to her near the docks in Theramore.", progress = "I thought I heard laughter coming from the barracks. Did you distribute those leaflets I gave you?", completion = "<Calia chuckles as you describe the guards' reactions to the propaganda.>\n\nJust as I'd hoped! I think it's safe to say any deserter agents who try to infiltrate Theramore will be laughed right out of town!", sourceObjectiveStatus = "unverified-source-field" }
quests[11134] = { id = 11134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Deserters", description = "Now that we've eliminated the deserters from Theramore, it's time to complete this operation. My local contacts have reported that the deserters base their operations in a ship moored on a small island to the southeast of the docks.\n\nArresting their leader, Gavis Greyshield, should cause the others to lose their will to fight. Find him within the ship and convince him to surrender. I wouldn't be surprised if he puts up a bit of a fight for show, but then surrenders when he understands he can't win.", sourceObjective = "Capture Gavis Greyshield, then report to Calia Hastings near the docks in Theramore.", progress = "Have you completed your assault on the deserter base?", completion = "Gavis' request isn't as outlandish as it might sound. With the proper handling, Lady Jaina can return the deserters to the fold, but that is her decision, of course.\n\nIt's been a pleasure working with you, {name}. Without your help, I doubt the operation would've gone so smoothly. When I make my report in Stormwind, it will name you as the {class} who ended the deserter threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11135] = { id = 11135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Headless Horseman", description = "The Headless Horseman is driven away, but he will return as long as Hallow's End looms.  {name}, end our misery, and the insane lament of the Horseman.  Face him when he is joined with his head, and destroy it!\n\nHe rests in the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glade.  Find his pumpkin shrine and say this:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nGo, {name}.  And may the Light go with you.", sourceObjective = "Find the Headless Horseman's pumpkin Shrine.", completion = "The origin of this shrine is unknown, but there is no doubt to whom it pays homage...", sourceObjectiveStatus = "unverified-source-field" }
quests[11136] = { id = 11136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disturbing Development", description = "Reports from our scout patrols have recently taken a disturbing turn. They tell of men wearing red Defias bandanas walking the Dreadmurk Shore north of Theramore's walls.\n\nWreckage in the area suggests they may be survivors of a shipwreck, but our information is limited. Captain Wymor at Sentry Point, a guard tower to the north of the city, is looking for help in following up on the reports.", sourceObjective = "Report to Captain Wymor at Sentry Point.", completion = "<The captain makes no effort to hide that he's assessing your abilities.>\n\nSo you've heard about the recent shipwreck off the coast? Good, I could use some help confirming my suspicions about the survivors. Welcome aboard, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11137] = { id = 11137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defias in Dustwallow?", description = "My scouts have reported a shipwreck just off the beach to the northeast. Shipwrecks aren't all that unusual out here, but the reports also indicated the survivors were all wearing red bandanas!\n\nThe Defias are craftsmen and guildsmen, not sailors. What are they doing at the site of a shipwreck on a continent they've no interest in?\n\nTheir leader is rumored to reside on a large island just off the coast to the northeast of the tower. Kill him and retrieve any documents you find in his possession.", sourceObjective = "Obtain the Defias Orders from Garn Mathers and bring them to Captain Wymor at Sentry Point.", progress = "Were you able to track down their leader?", completion = "<Captain Wymor accepts the orders from you and reads over them.>\n\nWhat in the world could 'precious cargo' refer to? The Defias have done some small time smuggling back in lands of Stormwind, but this seems out of their league. The language of these orders suggests a wealthy or noble patron.", sourceObjectiveStatus = "unverified-source-field" }
quests[11138] = { id = 11138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renn McGill", description = "From the wording of the orders you recovered, it looks like the first priority of the Defias will be to locate and secure whatever cargo they possessed.\n\nSI:7 has had a salvage diver named Renn McGill working out of Theramore for some time. When he heard about the shipwreck, Renn went north to dive near the islands the Defias now occupy.\n\nIf we're to beat the Defias to this cargo, we'll need his help. Look for him in the waters northeast of a small island just north of the island you visited earlier.", sourceObjective = "Bring the Defias Orders to Renn McGill in the waters off the Dreadmurk Shore.", progress = "Well met, {class}. What brings you out here?", completion = "<Renn looks over the orders.>\n\nSo there was valuable cargo on board! We have to locate it before the Defias recover it. These guys are no divers, but we're going to need some of their gear if you're to help me find the cargo.", sourceObjectiveStatus = "unverified-source-field" }
quests[11139] = { id = 11139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secondhand Diving Gear", description = "There's plenty of wreckage strewn across the bottom of the water from here to Alcaz, and the Defias have already got divers out there looking around. With the help of some of their gear, we can get you suited up and ready to join the hunt, but you'll have to do some creative \"borrowing\" first.\n\nSearch this island for a crate of diving gear and something to repair it with. When you've got them, bring them to me and I'll have your gear ready in no time!", sourceObjective = "Bring the Tool Kit and Damaged Diving Gear to Renn McGill in the Dustwallow Marsh.", progress = "Let's see what you managed to \"borrow\" from the Defias.", completion = "Wow, this is in worse shape than I'd thought, and these tools...\n\nWell, I said I'd get this back into working condition for you, so I'd better get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[11140] = { id = 11140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover the Cargo!", description = "Well, I was able to make enough repairs to this gear to let you dive for awhile, anyway. I wouldn't count on it holding out for a long time, though.\n\nThe wreckage of the ship is strewn along the bottom from the east coast of this island out toward Alcaz Island. While that helm holds out, locate pieces of the wreckage on the bottom between this island and Alcaz. Use this salvage kit to search the wreckage for pieces of the cargo. Be careful not to venture too close to Alcaz Island. Those hydra are fierce.", sourceObjective = "Bring 6 Salvaged Strongboxes to Renn McGill in Dustwallow Marsh.", progress = "Did your search of the wreckage reveal anything about the Defias cargo?", completion = "<Renn rifles through the contents of the strongboxes you recovered.>\n\nGood work. Now, let's see if our 'precious cargo' is in here....", sourceObjectiveStatus = "unverified-source-field" }
quests[11141] = { id = 11141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina Must Know", description = "You must bring news of our findings to Lady Jaina without delay! If the Defias were transporting a prisoner, there's no telling who it might be or if the person is still alive!\n\nOne thing is for certain, {name}. The Defias wouldn't go to all this trouble for some petty grudge. Their prisoner must have been someone of importance. Lady Jaina would know better than anyone else what these findings mean. You'll find her at the top of the mage tower at Theramore's center.", sourceObjective = "Speak with Lady Jaina Proudmoore in Theramore.", completion = "You and Renn have done excellent work in bringing this information to light and reporting it immediately. There's no denying the Defias have hatched some sinister plan to strike at Stormwind and its allies. There's a level of complexity here that's beyond anything they've ever attempted, which means they must have a wealthy sympathizer somewhere.", sourceObjectiveStatus = "unverified-source-field" }
quests[11142] = { id = 11142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey Alcaz Island", description = "It looks like Renn's hunch about Alcaz Island was right. We need to survey that island, but it would take a whole brigade of troops to fight our way in there.\n\nTheramore's defenses can't weather such a hit, so I've arranged with Cassa Crimsonwing, the apprentice to Theramore's gryphon master, to allow you to use one of her beasts to survey Alcaz from the air.\n\nAlcaz Island holds the key to the Defias' plans for their prisoner and perhaps the prisoner's identity itself.", sourceObjective = "Speak to Cassa Crimsonwing and use one of her gryphons to survey Alcaz Island. When your survey is complete, speak with Lady Jaina Proudmoore in Theramore.", progress = "Have you completed your aerial survey of Alcaz Island?", completion = "<Lady Jaina listens intently as you report the results of your aerial survey.>\n\nA rune circle, dragonkin? The Defias certainly have hedge mages among their ranks, but no one powerful enough to make use of such a thing!\n\nAnd why would the black dragonkin be interested in an island full of naga? There are many unanswered questions, but one thing is for certain: the Defias have a powerful ally in upper echelons of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[11143] = { id = 11143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Connection", description = "I've spoken with Inspector Tarem regarding the evidence you gathered from the ruins of the Shady Rest Inn. He seems certain that the hoofprints and the shield you found there point to the Grimtotem clan of tauren.\n\nWith reports of Grimtotem activity on the rise in the marsh, this has to be more than a mere coincidence. I'm sending you to speak with Captain Darill, who is something of an expert on the Grimtotems. Follow the road north out of town to North Point tower. It's the second outpost on the road.", sourceObjective = "Report to Captain Darill at North Point.", completion = "Captain Vimes thinks the Grimtotems are behind the destruction of the Shady Rest Inn? They wouldn't have been first on my list of suspects, but if Captain Vimes sent you here to follow up on a lead, he must have his reasons. Regardless, the Grimtotems have been a thorn in our side for some time and we're always glad to have the extra help.", sourceObjectiveStatus = "unverified-source-field" }
quests[11144] = { id = 11144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confirming the Suspicion", description = "The Grimtotems may be the most warlike of all the tauren clans, but they're by no means unorganized. If they're the ones who put the torch to the Shady Rest Inn, they'll have had orders from one of their clan elders.\n\nThere's a large Grimtotem settlement called Blackhoof Village to the northwest. They've been using it as a base to attack the tower, but I'll bet that you'll find the orders you're looking for there. Check the village's elders for traces of the orders you seek.", sourceObjective = "Bring the Grimtotem Battle Plan to Captain Darill at North Point Tower.", progress = "Were you able to find any trace of the orders?", completion = "<Captain Darill glances at the battle plan.>\n\nI'd say it doesn't get any clearer than this. They've taken it upon themselves to fight back against human settlements in the area and I have little doubt Theramore is next on their list.", sourceObjectiveStatus = "unverified-source-field" }
quests[11145] = { id = 11145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoners of the Grimtotems", description = "We're doing all we can to keep the Grimtotem raiders at bay, but they keep launching assaults on the tower. Even worse, they've managed to discover and capture the patrols the captain sends out to gather information and safeguard the road.\n\nI suspect the captives are being held in Blackhoof Village, to the northwest. Knowing the Grimtotems, the defenders of the village probably carry the keys to the prisoners' cages with them. I don't care what you have to do, {class}, just bring back my men alive.", sourceObjective = "Sergeant Lukas at North Point Tower wants you to free 5 Theramore Prisoners.", progress = "Did you manage to free the captives at Blackhoof Village?", completion = "The freed captives have already begun returning from Blackhoof Village. The information the captain is receiving from the prisoners will give us an advantage in our next battle against the Grimtotems.\n\nYou have my thanks and that of the men.", sourceObjectiveStatus = "unverified-source-field" }
quests[11146] = { id = 11146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Captor", description = "The patch of swamp to the northeast is home to a particularly nasty breed of raptors. We've lost more than one unwary soldier to them, but I think we can turn them against our Grimtotem neighbors.\n\nTake this rope and use it to capture bloodfen raptors or bloodfen screechers that you've subdued. I wouldn't try to capture one of the beasts until you've weakened them quite a bit in combat. It's going to be quite a struggle.", sourceObjective = "Sergeant Lukas at North Point Tower wants you to capture 6 raptors. You can capture either Bloodfen Raptors or Bloodfen Screechers.", progress = "Did you capture those raptors?", completion = "You look a little scratched up, but nothing major. You're certainly in a lot better shape than the Grimtotems will be when our new raptor friends get done with them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11147] = { id = 11147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleash the Raptors", description = "Now that we've got our raptors, our next move is to \"encourage\" them to attack the Grimtotems at Blackhoof Village to the northwest.\n\nI've got a leftover haunch of... well, it doesn't really matter what it is. It'll be your bait. Set it down on the ground in Blackhoof Village near the windmill in the center of the settlement. The raptors should take care of the rest, if their training took.", sourceObjective = "Sergeant Lukas at North Point Tower wants you to place the Raptor Bait near the windmill in Blackhoof Village.", completion = "<The sergeant doesn't bother to hide his grin.>\n\nGood. That ought to forestall a raid or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[11148] = { id = 11148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms of the Grimtotems", description = "If the equipment you found at the ruins of the inn belonged to a Grimtotem attack party, there's likely to be more just like it within their camp to the northwest.\n\nWe haven't been able to gather much information about Blackhoof Village, but judging from the size of the raiding parties, there's a substantial force based there.\n\nDo whatever you have to to capture some of their equipment so that we can compare it with your findings from the inn.", sourceObjective = "Captain Darill at North Point Tower wants you to bring him 7 Blackhoof Armaments.", progress = "Did you get those weapons from Blackhoof Village?", completion = "<Captain Darill inspects the armaments you've brought from Blackhoof Village.>\n\nThere's no doubt about it. These match the description exactly, but there's just one problem -- these have never been used in battle. Blackhoof Village must not be the only Grimtotem post in the marsh.", sourceObjectiveStatus = "unverified-source-field" }
quests[11149] = { id = 11149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabetha's Assistance", description = "I can't spare any men to help search for a second Grimtotem outpost, but I think I know of someone who might be able to help you.\n\nDeep in the Quagmire, to the south, there is a small farmstead owned by Tabetha. She may seem little more than an old hermit, but the truth is that she's a mage and scryer of some renown. Follow the road south to her farm and seek her help in finding the culprits responsible for the massacre at the Shady Rest Inn.", sourceObjective = "Speak with Tabetha at her farm.", completion = "So you want me to scry for Grimtotems, eh? And what will you say when I tell you there's no need?", sourceObjectiveStatus = "unverified-source-field" }
quests[11150] = { id = 11150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", sourceObjective = "Burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post, then return to Tabetha at her farm.", progress = "Have you put that torch to good use?", completion = "I hope the Grimtotems got the message. Any attempt to return will be met with far worse than a mere torch. My apprentices and I will see to that.", sourceObjectiveStatus = "unverified-source-field" }
quests[11151] = { id = 11151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice for the Hyals", description = "Although these Grimtotems were simply a nuisance to me, Captain Vimes will want to know of your deeds. Bring him the news that you have tracked down and dealt with those responsible for the burning of the Shady Rest Inn.\n\nIt's too late to save Jim Hyal's family, but perhaps the Grimtotems will think twice before attacking anyone connected to Theramore.", sourceObjective = "Speak to Captain Garran Vimes at Foothold Citadel in Theramore.", completion = "<The captain listens to your report intently.>\n\nWe have avenged James and his family, but not even that can restore what was destroyed.", sourceObjectiveStatus = "unverified-source-field" }
quests[11152] = { id = 11152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peace at Last", description = "I wish we had a way of letting James Hyal's wife and son know that we have brought their murderers to justice.\n\n<Captain Vimes produces a small wreath decorated with flowers.>\n\nThere are some who say that their spirits will know, even if we cannot reach them. It's not much, but I'd like you to lay this wreath at the Hyal family monument. It's one of the larger stones in the graveyard just north of Theramore's gates.", sourceObjective = "Captain Garran Vimes at Foothold Citadel wants you to lay the Wreath at the Hyal Family Monument.", progress = "Did you lay the wreath?", completion = "<Captain Vimes smiles slightly as you relate the events you witnessed at the Hyal family grave.>\n\nIt's good to know that they understand. You didn't tell them about James, did you?\n\nI'll deliver his wife's message to him, but I doubt he'll understand.", sourceObjectiveStatus = "unverified-source-field" }
quests[11156] = { id = 11156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direhorn Raiders", description = "The Grimtotems up at Direhorn Post, just to the north, are getting bolder by the day. At night, you can often hear them chanting about their deeds in battle against people who've tried to settle here.\n\nThey're determined to drive us from Tabetha's farm even though she's trained generations of apprentices here. We've defended the farm as best we can, but Apprentice Garion was wounded in the last attack.\n\nGo to Direhorn Post and kill any Grimtotem you can find! The attacks must stop.", sourceObjective = "Kill 12 Direhorn Grimtotems and return to Apprentice Morlann at Tabetha's Farm.", completion = "<Apprentice Morlann nods.>\n\nGood. Can't say I'll miss the company, if you can call it that. You'd think at least in the middle of the swamp you'd get some privacy, you know?", sourceObjectiveStatus = "unverified-source-field" }
quests[11158] = { id = 11158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodfen Feathers", description = "Are you startled by Brogg's presence here, little {race}? Don't worry. Goblins at Mudsprocket are Brogg's friends and you can be, too.\n\nBrogg left Brackenwall Village when new overlord not take revenge against black dragonkin for destroying old home and killing many of Brogg's old friends. Brogg come here to lay friends spirits to rest and avenge them, but Brogg need help preparing. For ritual, Brogg need feathers with strong magic, like ones worn by raptors at Bloodfen Burrow to the west of town.", sourceObjective = "Bring 5 Bloodfen Feathers to Brogg at Mudsprocket.", progress = "<Brogg looks at you hopefully.>\n\nYou bring Brogg feathers?", completion = "<Brogg accepts the feathers.>\n\nBrogg pleased with these feathers. Very strong magic. Brogg not know what raptors do to give feathers power, but raptor feathers always best for ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[11159] = { id = 11159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of Stonemaul Hold", description = "Brogg has completed the totem that will put the spirits of his friends to rest. When the dragonkin came, they killed all Stonemaul who did not flee. Brogg fled with Overlord Mok'Morokk, hoping to lead a counterattack with other Stonemaul survivors.\n\nThe counterattack never came and the spirits of the Stonemaul dead still haunt Brogg and the others. Take this totem north to Stonemaul Ruins and use it near ogre skeletons to draw the spirit to you. Defeat the spirit to give it rest with its bones.", sourceObjective = "Brogg, at Mudsprocket, wants you to put 10 Stonemaul Spirits to rest.", progress = "Brogg must know, have you brought peace to the violent spirits of the Stonemaul?", completion = "Brogg thanks you for your help, although he knows Overlord Mok'Morokk never will. At least surviving Stonemaul can finally focus on problems with the living and leave dead where they belong. Only one thing remains for Brogg to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11160] = { id = 11160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banner of the Stonemaul", description = "When the dragons came and took over Brogg's old home, Stonemaul ogres fled and left everything behind, including clan's banner.\n\nBrogg knows banner was kept deep in Stonemaul ogre mound, but these days it's called Den of Flame. Brogg must have clan banner to get his revenge on dragons who killed his friends.\n\nBrogg's clan's old mound, Den of Flame, is northwest of Mudsprocket and crawling with dragonkin. Banner will be deep inside the cave. Be careful, {name}.", sourceObjective = "Retrieve the Stonemaul Banner and bring it to Brogg at Mudsprocket.", progress = "You bring Stonemaul banner?", completion = "You have Brogg's thanks, {name}. Brogg has big plans for clan banner.", sourceObjectiveStatus = "unverified-source-field" }
quests[11161] = { id = 11161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of Enmity", description = "To make the totem Brogg will need for his ritual, he must use the essences of the creatures who killed his friends. The hate and anger of Brogg's enemies will fuel the magic of his vengeance.\n\nTrack down Firemane ash tails, scouts, or scalebanes and use Brogg's totem on their corpses. Only when the dragonkin die will they give up their essences.\n\nThe creatures you seek swarm over the Den of Flame to the northwest and the Stonemaul Ruins to the north.", sourceObjective = "Bring 10 Black Dragonkin Essences to Brogg at Mudsprocket.", progress = "Do you have the essences? Brogg must have them to avenge his friends!", completion = "You have Brogg's thanks, {name}. Once Brogg adds their magic to the totem, it will be able to redeem the spirits of Brogg's fallen friends.", sourceObjectiveStatus = "unverified-source-field" }
quests[11162] = { id = 11162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge to the Black Flight", description = "Brogg relishes the thought of taking his revenge on the black dragonkin of the marsh. {name}, you have been very helpful in preparing for this moment. Will you help?\n\nTake Brogg's clan banner and travel east until you see a cave like a dragon's mouth. At the entrance to that cave, plant Stonemaul banner and issue Brogg's challenge to Onyxia.\n\nBrogg and the Stonemaul will have their lands back!", sourceObjective = "Plant the Stonemaul Banner near the entrance to Onyxia's Lair, wait for Onyxia's response, then return to Brogg at Mudsprocket.", progress = "Brogg will have his revenge!", completion = "<Brogg listens as you recount your experience at the entrance to Onyxia's lair.>\n\nBrogg suspected Onyxia would be too much of a coward to confront you. Just like black dragonflight to attack when victory is guaranteed.\n\nBrogg is grateful for your help, {name}, and he will never forget what you have done for him. Brogg will never give up his quest to bring Stonemaul back where they belong.", sourceObjectiveStatus = "unverified-source-field" }
quests[11163] = { id = 11163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercover Sister", description = "<Donna looks around and then whispers to you.>\n\n{name}, what I'm about to tell you must remain confidential, understood?\n\nI've been sent by the Shattrath Peacekeepers to infiltrate Budd's gang here. Truth be told, since you first arrived you've been a key person of interest in my investigation. \n\nBut your deeds have since cleared you of any suspicion. In fact, for your slaying of the crazed warlord, Zul'Jin, I'm compelled to reward you for your efforts.", sourceObjective = "Report to Donna Brascoe to collect a reward for your heroism in Zul'Aman. Donna is currently stationed in the Ghostlands, just outside Zul'aman.", completion = "<Donna looks around and then whispers to you.>\n\n{name}, what I'm about to tell you must remain confidential, understood?\n\nI've been sent by the Shattrath Peacekeepers to infiltrate Budd's gang here. Truth be told, since you first arrived you've been a key person of interest in my investigation. \n\nBut your deeds have since cleared you of any suspicion. In fact, for your slaying of the crazed warlord, Zul'Jin, I'm compelled to reward you for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[11164] = { id = 11164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuskin' Raiders", description = "'Ey mon! You be new around 'ere, eh? Lemme ask a favor of ya.\n\nBudd's been refinin' his forest troll disguise. Says that he be close now - just be needin' one last touch. Tusks.\n\nMy skinnin' talents be wasted 'ere. Somethin' about yankin' troll tusks be makin me queasy. \n\nBring me back 10 troll tusks, eh mon?", sourceObjective = "Prigmon needs you to collect 10 Forest Troll Tusks from the trolls in Zul'Aman. Bring them to him at Budd's camp in the Ghostlands.", progress = "Hurry, mon!\n\nBudd be sendin' me into Zul'Aman alone to test his mask if I don't be givin' him those tusks soon!", completion = "Ahh yeah, these be just what I be needin'!\n\nHere be the payment I promised ya, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11165] = { id = 11165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Troll Among Trolls", description = "Lissen mon, there be sumthin' else needs doin fer ol' Prigmon.\n\nZungam, my good-fer-nuthin' cousin, be stuck inside Zul'Aman. He still be alive too - I seen his signal flare just last night!\n\nI should be lettin' him rot fer gettin' me tied up in this mess, but he be owin' me big money.\n\nDo what ya can to help him out, then leave the collectin' to me!", sourceObjective = "Prigmon has tasked you with locating and assisting his cousin Zungam, somewhere within Zul'Aman.", completion = "I be free!\n\nDey took most everyting when dey nabbed me, but here - take the last of my coin fer your troubles.\n\nAnd the least I can be doin' is stickin' around to offer my services....", sourceObjectiveStatus = "unverified-source-field" }
quests[11166] = { id = 11166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "X Marks... Your Doom!", description = "How did those fools fail? I told them to be careful - even gave them disguises to help them blend in. Ahh, well. The bright side of their failure is that this opportunity falls to you.\n\nSucceed, and you'll be well on your way to joining my crew and sharing in the immeasurable fame that will soon be mine. Not that I need any more, mind you.\n\nThere are yet a few portions of my map that require further exploration before our excavation can be initiated....", sourceObjective = "Enter Zul'Aman and visit Halazzi's Chamber, Jan'alai's Platform, and Akil'zon's Platform. Report the details of those areas to Budd, at his camp in the Ghostlands.", progress = "I trust that my hand-crafted disguises have given you adequate protection in Zul'aman.\n\nHave you scouted those areas for me? Or shall I begin looking for your replacements?", completion = "<Budd struggles to maintain his composure.>\n\nErr - So, {name} - it's, uhhh,  about time you returned. Yes - in fact you're holding up the entire operation.\n\nNow then, let's get to filling in this map....", sourceObjectiveStatus = "unverified-source-field" }
quests[11169] = { id = 11169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem Weapon", description = "During the last Grimtotem attack, I was wounded, but not before I managed to capture a curious totem our enemies were using against us.\n\nIt seemed to be emitting raw bolts of energy during the battle, but in all my experiments, I haven't managed to figure out how it works. I'll loan the totem to you if you agree to help me test it.\n\nThe watery areas surrounding the farm are home to pesky mottled drywallow crocolisks and drywallow daggermaws. Try fighting the crocolisks near the totem.", sourceObjective = "Apprentice Garion at Tabetha's Farm wants you to test the Captured Totem on 10 Mottled Drywallow Crocolisks or Drywallow Daggermaws.", progress = "Have you had any luck testing the totem?", completion = "<The apprentice listens as you describe your experiment.>\n\nA haze and some lightning? That's it? There's got to be more to the totem than just that! The Grimtotems aren't likely to bring something like this to the battlefield unless it has some kind of utility.", sourceObjectiveStatus = "unverified-source-field" }
quests[11171] = { id = 11171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hex Lord? Hah!", description = "Excellent! Everything's nearly ready for my grand entrance into Zul'Aman.\n\nYou've done a fine job, {name}. I've spoken with my crew and they're warming up to you nicely. I'd say you're very close to becoming a permanent member of the team. Only one thing remains for you to do - dispatch that 'Hex Lord' fellow.\n\nNothing to it, really. You stand up to this wretch and he'll likely just turn and run. Weaker, older trolls just add intimidating titles to their name to make up for their deficiencies, you see?", sourceObjective = "Budd Nedreck in Hatchet Hills wants you to kill Hex Lord Malacrass in Zul'Aman.", progress = "I hope you appreciate the magnitude of the opportunity I've given you, {name}.\n\nHave you taken care of old Malacrass yet?", completion = "Finally! Now that the light work is done, I can at last make yet another mark on history. But first, there's one small matter to attend to - You....\n\nI'm afraid, {name}, that the time has come for me to let you go. I feel that your potential has been reached here, if not far exceeded.\n\nDon't feel bad, though. After all, it takes an exceptional type of individual to participate in such extraordinary events and not lose their wits. And look here, I have a little something for you to remember me by.", sourceObjectiveStatus = "unverified-source-field" }
quests[11172] = { id = 11172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zeppelin Crash", description = "Not long ago, a goblin zeppelin crashed to the east. A representative of the Steamwheedle Cartel passed through here a few days ago.\n\nShe was looking for information about the zeppelin's cargo and it's pilot, Beezil, but none of us really got a good look at the crash. I doubt she'll be able to clean up after the wreck by herself, much less recover whatever cargo the vessel might have carried.\n\nIf you have time, you may want to check up on her out at Beezil's Wreck, due east of here, near the mountains.", sourceObjective = "Speak with Moxie Steelgrille at Beezil's Wreck.", completion = "So those hermit mages sent you? How can I be sure that I can trust you?\n\nI suppose I can use the help. There's not much here a mage would be interested in, anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[11173] = { id = 11173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reagent Thief", description = "If there's one thing you can count on Apprentice Morlann to do, it's whine about reagents.\n\nNormally, I just ignore him, and it never works. This time, I'm going to try something different.\n\nMaybe if I replace the missing reagents before he notices, he'll leave me alone. The most common reagent we both use is marsh venom, which comes from the darkfang creepers and noxious shredders in the marsh north of the farm. If you bring me the venom, I'll replace it before Morlann notices it's gone.", sourceObjective = "Bring 6 vials of Marsh Venom to Apprentice Garion at Tabetha's Farm.", progress = "Did you get that venom? Morlann's going to discover that it's gone any moment now...", completion = "<Apprentice Garion inspects the venom.>\n\nThis is absolutely perfect! He'll never know the difference.", sourceObjectiveStatus = "unverified-source-field" }
quests[11174] = { id = 11174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrosion Prevention", description = "Just look at this area! It's swarming with oozes. If I don't find some way to keep them under control, they'll corrode the wreckage and the zeppelin's cargo!\n\nI can't go back empty-handed, {class}! Help me dissolve these oozes before they've digested everything!\n\nThis device, when powered, will concentrate energy on the slimes, causing them to explode. The zeppelin's fragmented power core should power the device. The one near the main crash works all the time, but the others flicker on and off.", sourceObjective = "Moxie Steelgrille wants you to dissolve 10 oozes and report back to her at Beezil's Wreck.", progress = "Did you make any progress against those oozes?", completion = "Well, it does look a little cleaner out there...\n\nI suppose it's time to get down to the business of salvaging this wreckage.", sourceObjectiveStatus = "unverified-source-field" }
quests[11177] = { id = 11177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit of Swamplight Manor", description = "There's a fellow the locals know as \"Swamp Eye\" Jarl, who lives alone out in the swamp. Sometime ago he \"took over\" Swamplight Manor after the previous owners disappeared under mysterious circumstances.\n\nI like to send someone to check up on him every once in a while. He kind of reminds me of my grandfather, you know? Some say he's not quite right in the head.\n\nIf you're headed northwest on the road out of Theramore, you'll find Swamplight Manor in the Witch Hill area, before the road turns west.", sourceObjective = "Speak to \"Swamp Eye\" Jarl at Swamplight Manor.", completion = "Get off my lawn... unless, that is, you want to help old \"Swamp Eye\" with a little bit of cooking. Whad'ya say?", sourceObjectiveStatus = "unverified-source-field" }
quests[11178] = { id = 11178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Warlord", description = "As you examine the pulsating vial, your thoughts turn to the petulant little man outside Zul'Aman.\n\nYou can't wait to see Budd's expression when he sees this!", sourceObjective = "Bring the Blood of Zul'jin to Budd at his camp in the Ghostlands, outside Zul'Aman.", progress = "<Budd tries to mask his displeasure at your presence.>\n\nYou again....\n\nI don't know how else to say it - I'm simply too busy with my preparations to hold your hand any longer.\n\nTrust me, {name}, it's all for the best. Perhaps, by some miracle, you might eventually build a name for yourself.\n\nIf so, you'll be able to say that you got your start from the incomparable Budd Nedreck!", completion = "Th-the Blood of Zul'jin himself you say?\n\n<Gathering himself, Budd continues>\n\nWell, I appreciate the gesture, {class}, but I could've taken him down with ease. There's no way he was as fearsome as the legends say. These things have a way of being utterly overstated, as you'll learn in time. More likely, the pitiful old cretin was overcome with arthritis!\n\nAnyway, I suppose it was the least you could do as payment for the kindness I've shown you here.\n\nNow off with you - I must dispose of this vial!", sourceObjectiveStatus = "unverified-source-field" }
quests[11180] = { id = 11180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Haunting Witch Hill?", description = "I traveled out here to pay Jarl a visit at his new home and it's been a nonstop horror show ever since! There's something seriously wrong here and I can't be the only one who sees it...\n\nHave you seen the ghosts and corpses shambling about Witch Hill? I've a feeling that if anyone knows what happened here, it is them. Seek out these risen husks and risen spirits in the surrounding area, grant them rest through combat, and see what you can learn from them before this evil consumes Jarl!", sourceObjective = "Mordant Grimsby at Swamplight Manor wants you to gather information from 10 Risen Husks or Risen Spirits.", progress = "What have you learned from the spirits haunting this place?", completion = "<Mordant produces a small sheet of paper and a pen, beginning to scribble down notes on your findings.>\n\nFrom your findings, the spirits in this place must amount to everyone who ever lived on this land, not just the previous occupants.\n\nSomething has been corrupting and killing them. Those who follow don't learn the truth until it's too late. We have to put an end to this, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11181] = { id = 11181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Witch's Bane", description = "In my years as an herbalist, I've often observed that nature will provide subtle cures to the most vexing of problems. I've read that hedge mages and witch doctors often use the smoke of an herb known as witchbane to draw evil from its hiding places.\n\nIf true, this would mean witchbane should be growing near the shallow waters of Witch Hill. You should be able to identify it by its broad leaves and reddish central stalk. Bring me any of the herb you can find, {name}. It may be our only hope.", sourceObjective = "Bring 9 sprigs of Witchbane to Mordant Grimsby at Swamplight Manor.", progress = "Were you able to gather any of the herb? We must work quickly, before whatever evil is behind this infestation consolidates its hold on this area.", completion = "<Mordant accepts the bunch of herbs from you.>\n\nThese match the description exactly! I prepared the torch while you were out. All that remains is to fasten the herbs to the end here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11183] = { id = 11183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Witch Hill", description = "The torch is ready. Plant it at the end of the dock and be prepared to face whatever comes forth.\n\nI have no idea what the torch's smoke may reveal... if anything emerges at all. I must say, I have my doubts about this kind of folk magic, but we haven't time for anything else. For your sake and Jarl's, I wish you luck.", sourceObjective = "Mordant Grimsby at Swamplight Manor wants you to plant the torch at the end of the dock and defeat anything that appears.", progress = "Is it over?", completion = "It worked?\n\n<Mordant clears his throat.>\n\nI mean... it worked! Jarl and I are in your debt, {name}. Now the only remaining problem is my friend's taste in furniture, and I'm afraid that won't be solved as easily.", sourceObjectiveStatus = "unverified-source-field" }
quests[11184] = { id = 11184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Goreclaw the Ravenous", description = "Travelers and Steamwheedle personnel working in the field are advised to avoid the Bloodfen Burrow to the west of town.\n\nThe area is overrun with raptors lead by the cruel and cunning Goreclaw the Ravenous, who has already killed at least two Steamwheedle engineers.\n\nDrazzit Dripvalve has authorized a generous reward to be paid to the individual who rids Mudsprocket of this menace.", sourceObjective = "Kill Goreclaw the Ravenous and report to Drazzit Dripvalve at Mudsprocket.", progress = "You look pretty satisfied with yourself. Come to claim the bounty on that monstrous raptor?", completion = "Thank goodness someone's finally taken me up on that offer. I was just thinking that I might need to triple the reward to get that stupid raptor killed, and our budget couldn't afford that!", sourceObjectiveStatus = "unverified-source-field" }
quests[11185] = { id = 11185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Apothecary's Letter", description = "Recovered from the body of a Forsaken apothecary, this letter contains alarming evidence of a close alliance between the Grimtotems and the new masters of Lordaeron.\n\n\"As a demonstration of good faith and a symbol of our newfound trust, we have dispatched Apothecary Cylla to aid you in battling our mutual enemy in the land of Kalimdor. None will stand before our combined might and determination.\"\n\nThis letter should be brought to the attention of the SI:7 agent at Tabetha's Farm, Andello Porter.", sourceObjective = "Bring the Sealed Letter to Andello Porter at Tabetha's Farm.", progress = "What is that you're carrying, {class}?", completion = "<Andello reads the letter, shocked at its contents.>\n\nWe've long had misgivings about the cooperation between the Horde and the Forsaken, and this only confirms those suspicions. With the backing for Forsaken magic and arms, the Grimtotems would become an even more fearsome enemy. The balance of power in Kalimdor could shift considerably.", sourceObjectiveStatus = "unverified-source-field" }
quests[11186] = { id = 11186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Treachery?", description = "Recovered from the body of a Forsaken apothecary, this letter hints at an underground correspondence between Undercity and the Grimtotem leadership.\n\n\"As a demonstration of good faith and a symbol of our newfound trust, we have dispatched Apothecary Cylla to aid you in battling our mutual enemy in the land of Kalimdor. None will stand before our combined might and determination.\"\n\nPerhaps Nazeer Bloodpike in Brackenwall Village will know how to handle this information.", sourceObjective = "Bring the Sealed Letter to Nazeer Bloodpike in Brackenwall Village.", progress = "What is that you're carrying, {class}?", completion = "If this is what it appears to be, the Forsaken have some explaining to do!\n\nThe antics of the Grimtotems have long tried the Warchief's patience. We have traditionally treated it as a matter to be settled among the tauren people, but this letter may change it.\n\nIt will take time to investigate these suspicions, but do not speak to anyone of what you have seen this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[11191] = { id = 11191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Old Lighthouse", description = "The old lighthouse out to the east hasn't worked for some time, but Babs Fizzletorque has gotten it into her head to get it working again.\n\nI don't know how she plans to do it by herself, but she claims that it'll make the movement of ships and goods into the docks smoother, so I can't really object. Drawing duty on the docks is really nothing to complain about when you could be on the front lines, you know?", sourceObjective = "Speak to Babs Fizzletorque at the lighthouse on the island east of Theramore.", completion = "Good. I can use all the help you can offer. My first priority is to get that lamp re-lit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11192] = { id = 11192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thresher Oil", description = "The old log in the lighthouse indicates that the lamp was fueled with oil from the threshers that live along the coast here.\n\n<Babs wrinkles her nose at the mention of such outdated technology.>\n\nI suppose it's a practical, if inelegant solution. The log says that the oil taken from the youngest murk threshers works the best, and those live right underneath the docks of Theramore.\n\nIf you're up for it, would you help resupply the lighthouse with fuel?", sourceObjective = "Bring 4 containers of Thresher Oil to Babs Fizzletorque at the lighthouse near Theramore.", progress = "Were you able to get any of that thresher oil?", completion = "Well, I have my doubts, but this is the only solution available right now. Once we have it up and running, I'm sure there will be time to look at other ways to fuel the lamp.", sourceObjectiveStatus = "unverified-source-field" }
quests[11193] = { id = 11193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dastardly Denizens of the Deep", description = "You know, it's amazing what you can find in that old lighthouse. After I lit the lamp, I noticed this book in one of the old trunks up there.\n\n<Babs holds up the book and reads the title dramatically.>\n\n\"Dastardly Denizens of the Deep!\"\n\nWhy, I think I might swoon if I ever saw one of these! I'm sure it's good for a laugh or two, but I simply don't have time for reading right now.\n\nYou know who might enjoy it, though... that fishmonger on the docks, \"Dirty\" Michael Crowe. He collects old books.", sourceObjective = "Bring Dastardly Denizens of the Deep to \"Dirty\" Michael Crowe on the Theramore docks.", progress = "What'll it be today? The snook is quite good.", completion = "Well, now, that was thoughtful o' Babs to send that over. I don't know if you've leafed through it or not, but there's a lot of truth to the tales in that book. Sailors didn't just make it all up, you know.", sourceObjectiveStatus = "unverified-source-field" }
quests[11194] = { id = 11194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is it Real?", description = "Oh, I'm sure you and Babs had a good laugh over the outlandish descriptions and sketches in the book, but have you stopped to consider there might be some truth to the legends?\n\nIf you listen closely enough, I bet you can still hear sailors talk about Tethyr, the sea creature the book says lives right here! Of course, if you wanted to know for sure, you could always ask old Nat Pagle.\n\nHe's got a small fishing camp on a little island in Tidefury Cove, which is southwest across Dustwallow Bay.", sourceObjective = "Talk to Nat Pagle at Nat's Landing in Tidefury Cove.", completion = "So you want to know about sea monsters? Hmm... well, I'll make you a deal, but it's going to involve a lot of alcohol and some embarrassment on your part.", sourceObjectiveStatus = "unverified-source-field" }
quests[11195] = { id = 11195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playin' With Dolls", description = "I'm touched, {name}, an' dat be da truth. I'm not rememberin' the last time a {race} helped Zungam outta trouble.\n\nI snatched this from one of them savages when he was busy chainin' me up. It don't look like much, but if anyone can determine its worth, it be my good friend, Griftah!\n\nIf ya be makin' it outta here alive, it might be worth takin' this to him out in Shattrath City.", sourceObjective = "Take the Tattered Voodoo Doll to Griftah in Shattrath City.", progress = "Hey, {name}! I hear ya been workin' yer way into Budd's crew. Ya won't live to regret that move, friend, I can promise ya that.\n\nWhatcha got there, mon?", completion = "Hey now, where ya be gettin' this?\n\nNo, no, don't tell me - this be comin' from the Hex-Lord himself! It all be clear now. Strong mojo! The bearer of this relic, no matter how many disgraces he be sufferin', be always honored by his peers. Incredible!\n\n<As Griftah holds the doll in the air, a small, rusty charm falls from around its neck. The troll begins to discard it, but then turns toward you with a gleam in his eye.>\n\nI gots no coins right now, mon, but ya be welcome to this here...", sourceObjectiveStatus = "unverified-source-field" }
quests[11196] = { id = 11196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEMP X", description = "Lissen mon, there be sumthin' else needs doin fer ol' Prigmon.\n\nZungam, my good-fer-nuthin' cousin, be stuck inside Zul'aman. He still be alive too mon - I seen his signal flare just last night!\n\nI should be lettin' him rot fer gettin' me tied up in this mess, but he be owin' me big money.\n\nDo what ya can to help him out, then leave the collectin' to me!", sourceObjective = "Prigmon has tasked you with locating and assisting his cousin Zungam, somewhere within Zul'aman.", sourceObjectiveStatus = "unverified-source-field" }
quests[11198] = { id = 11198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Down Tethyr!", description = "Sea monster or no, we're not going to risk the safety of our shipping. I've ordered our best marksmen to prepare for a confrontation with this Tethyr. The artillerymen have augmented the dock's defenses with three mortars.\n\nI'm going to order the lighthouse's lamp illuminated. If Tethyr does attack, it will be your job to operate the mortars and take down the beast before it can kill all of the marksmen. I wouldn't stand in one place too long, though. Using the mortars is likely to draw its attention.", sourceObjective = "Major Mills at the Theramore docks wants you to defeat Tethyr.", completion = "Well done, {name}! I'll admit, when I caught my first glimpse of that beast, I had doubts about our ability to defend the docks, but you held together the defenders brilliantly!", sourceObjectiveStatus = "unverified-source-field" }
quests[11200] = { id = 11200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More than Coincidence", description = "We've gleaned as much as we can from the ruins of the inn. I'm concerned about where the investigation will lead us from here, but we must know the truth.\n\nBetween the hoofprints and the shield with Mosarn's mark, I'm lead to believe that the Grimtotems may have been involved. They've recently established a settlement in the swamp, Blackhoof Village to the northeast. Travel to Blackhoof Village and search for more arms of Mosarn's manufacture.", sourceObjective = "Krog at Brackenwall Village wants you to bring him 7 Blackhoof Armaments.", progress = "What did your search of Blackhoof Village reveal?", completion = "<Krog inspects the weapons and armor you've brought from Blackhoof Village.>\n\nThis is unmistakably the work of Mosarn. Questioning him further may draw too much attention, but we have a bit more freedom in dealing with the Grimtotems.", sourceObjectiveStatus = "unverified-source-field" }
quests[11201] = { id = 11201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem Plot", description = "With the activities of the Grimtotems in Thousand Needles brought to light, many tauren now regard them with suspicion.  We've seen high-ranking Grimtotems engage in murder and kidnapping to advance their interests and I fear we may become their next target.\n\nBlackhoof Village, to the northeast, near Bluefen, is a large new Grimtotem settlement. Their leaders, the elders, will all have orders from Thunder Bluff. See if you can capture the orders and piece them together to learn the Grimtotems' plans.", sourceObjective = "Bring the Grimtotem Battle Plan to Krog at Brackenwall Village.", progress = "Were you able to find any trace of the orders?", completion = "<Krog reads over the battle plan.>\n\nThere's no doubt in my mind that the Grimtotems are moving against the humans. What I don't understand is what their intentions are toward us. The actions of the Grimtotems have caused tension within the Horde in the past, but the Warchief has always diffused it.", sourceObjectiveStatus = "unverified-source-field" }
quests[11203] = { id = 11203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Tabetha", description = "The arms you captured in Blackhoof Village have not seen any combat beyond mere training exercises, which means the Grimtotems who destroyed the Shady Rest are still at large.\n\nTo the south, in the heart of the Quagmire, lives the witch Tabetha. Though she is a human, she has dealt honorably with us and trained some of our mages.\n\nAsk her for assistance in tracking down the band of Grimtotem responsible for burning the inn. The Alliance must not be allowed to think we were complicit in the attack.", sourceObjective = "Speak with Tabetha at her farm in the Quagmire.", completion = "<Tabetha smiles slightly.>\n\nKrog wishes me to scry for the Grimtotems, eh? Well, I have no need of magic in this case.\n\nIt seems we have a mutual enemy. The Grimtotems have built an outpost nearby and are a constant thorn in the side of me and my students.", sourceObjectiveStatus = "unverified-source-field" }
quests[11204] = { id = 11204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Krog", description = "I hope I've been helpful to you and I'm sorry I can't offer more information. My apprentices and I produce such a large volume of arms and armor that it's almost impossible to recall details about any individual piece.\n\nNot only do we outfit the braves defending tauren lands, but the Grimtotems have a particular fondness for my work. A seasoned warrior knows good work when he sees it.", sourceObjective = "Speak with Krog at Brackenwall Village.", completion = "He actually said that the Grimtotems are his biggest customers? Mosarn gave us more help than he knows. With this much pointing toward the Grimtotems, I think we just found our first suspects.", sourceObjectiveStatus = "unverified-source-field" }
quests[11205] = { id = 11205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", sourceObjective = "Burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post, then return to Tabetha at her farm.", progress = "Have you put that torch to good use?", completion = "The Grimtotems should have no trouble understanding our latest message.\n\nAs for you, your contact at Brackenwall Village will want to know of your success. I know the destruction of the Shady Rest Inn could be a source of tensions between the Horde and Alliance. If I encounter any investigators from Theramore, I will gladly tell them the Grimtotems acted on their own.", sourceObjectiveStatus = "unverified-source-field" }
quests[11206] = { id = 11206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice Dispensed", description = "I doubt the Grimtotems will give up their campaign to drive humans from the marsh. At least we have dealt with the perpetrators of the crimes at the Shady Rest Inn.\n\nI'm sure the investigator who sent you doesn't need to be told this, but the Horde can no longer afford not to rein in the Grimtotems. There will be a day when their actions will put the Horde in a regrettable position.\n\nNeither Lady Jaina nor Warchief Thrall desire another war, but are they willing to do what's necessary to avoid it?", sourceObjective = "Return to Krog at Brackenwall Village.", completion = "<Krog listens to your report.>\n\nI'm impressed, {name}. I would've thought that the Grimtotem criminals would've been more difficult to locate. \n\nTabetha's warnings have not fallen on deaf ears, but it is not my place to chastise the Grimtotems. I will, of course, mention it in my report to the Warchief. Do not speak of it to anyone until Thrall has dealt with the Grimtotems. You have done well in solving the mystery of the Shady Rest and sparing us from the suspicion of Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[11207] = { id = 11207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secure the Cargo!", description = "This zeppelin was carrying six months' worth of supplies to us at Mudsprocket! Sure, they've been able to barter for some of what they need, but they won't hold out forever.\n\nI've been sent out here to recover what I can of the cargo, but the wreckage is scattered all over the marsh in this area. I'm sure a lot of the cargo didn't survive the crash, but are you willing to help me recover what we can?", sourceObjective = "Moxie Steelgrille at Beezil's Wreck wants you to recover 8 pieces of Zeppelin Cargo.", progress = "<Moxie looks frantic with worry.>\n\nDid the cargo survive? Did you find any of it?", completion = "Wow! You certainly found a lot more than I expected would be out there. I'm not sure how much Drazzit thought we were going to find out here, but he's going to have to be happy with this for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[11208] = { id = 11208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery for Drazzit", description = "Drazzit will expect to hear something from me soon, but I don't think the site is secure enough for me to leave. If you have time, would you be willing to take some of the salvaged cargo down to him at Mudsprocket?\n\nIf you haven't been there yet, it's a small settlement to the southwest of here, beyond the Stonemaul Ruins. You can take the road there from Tabetha's Farm, too. When you get to Mudsprocket, the guy you're looking for is Drazzit Dripvalve.", sourceObjective = "Take the Zeppelin Cargo to Drazzit Dripvalve at Mudsprocket.", progress = "Yes?", completion = "<Drazzit accepts the cargo from you.>\n\nI'm so hungry, I could eat a dragon! Thank goodness Moxie finally got some of that cargo down here. We've been reduced to playing dice against the ogre for whatever he's managed to kill on his hunting trips!", sourceObjectiveStatus = "unverified-source-field" }
quests[11209] = { id = 11209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nat's Bargain", description = "So you found a copy of Dastardly Denizens of the Deep, did you? Well, I can tell you from experience, it's all true. I've even seen a few of 'em with my own eyes.\n\nBut you want to know about Tethyr.  I said I'd make you a deal, so here's what I want you to do. I'm working on a new line of baits, but I haven't tested this one yet.\n\nJust take this paste -- yeah, it smells a little foul -- smear it on yourself, and swim over to that wrecked ship to the southwest. If you survive, let me know how it works!", sourceObjective = "Nat Pagle at Nat's Landing wants you to test his new fish bait.", progress = "Remember, the deal is \"don't come back until something bites you.\"", completion = "Not bad at all, but you know, I think I'd get a bath in as soon as possible, if I was you.\n\nNow, about your sea monster...\n\nHelp yourself to a brew or two in the meantime.", sourceObjectiveStatus = "unverified-source-field" }
quests[11210] = { id = 11210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, It's Real", description = "Yes, Tethyr is certainly real, and he lives in the waters off Theramore.\n\nHas a thing for bright lights. He's the reason they shut down the lighthouse in the first place, you know...\n\nAnd if you light it up again, he'll come right back. But no one in their right mind would do that.\n\nSo that must be your plan! It's been good sharing a drink with you, but don't blame ol' Nat if Tethyr REALLY turns you into fish bait. If you're going to do this, make sure you consult Major Mills at the Theramore docks.", sourceObjective = "Speak with Major Mills at the docks in Theramore.", completion = "<You recount your experiences with Nat Pagle, carefully omitting the portion about the 'bait test.'>\n\nWell, it sounds like we've got our work cut out for us. I'll make the preparations.", sourceObjectiveStatus = "unverified-source-field" }
quests[11211] = { id = 11211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help for Mudsprocket", description = "When that goblin... what's her name... Boxie, Foxy... Moxie, that's it! Anyway, when she came through here on her way to the zeppelin wreck, she said the town of Mudsprocket was having some problems.\n\nThat crashed zeppelin was bringing them fresh supplies. If you follow the road south from here, past the Stonemaul Ruins, you'll eventually come to Mudsprocket.\n\nWhy don't you check in with Drazzit Dripvalve down there and see if there's anything you can do to help?", sourceObjective = "Speak with Drazzit Dripvalve at Mudsprocket.", completion = "It's good of Tabetha to send you down here. I'd prevail upon her for some food until the wreckage from the zeppelin is taken care of, but I know she's got none to spare at the moment. If you're feeling adventurous, I've posted a bounty for the death of a particularly nasty raptor.", sourceObjectiveStatus = "unverified-source-field" }
quests[11212] = { id = 11212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabetha's Farm", description = "Deep in the heart of the swamp lives an old woman named Tabetha. We've never really known much about her, save that she's a good deal older than she appears. She's helped us from time to time and helped keep the peace here between the Horde and our forces.\n\nShe used to keep in regular contact, but we haven't received one lately.\n\nCould you check in with her when you have time? Just follow the road beyond North Point Tower, where it turns south and into the Quagmire. You can see her farm from the road.", sourceObjective = "Speak with Tabetha at her farm in the Quagmire.", completion = "It's good of Theramore to send someone. Your guard friend's suspicions were correct. We've got some new neighbors, and they aren't the kind you'd bring a casserole.", sourceObjectiveStatus = "unverified-source-field" }
quests[11213] = { id = 11213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Check Up on Tabetha", description = "A human woman named Tabetha lives on a small farm near the middle of the marsh. Ordinarily, I wouldn't associate with a human, but her help has proven useful at times.\n\nUnfortunately, she's been out of touch for quite some time now and I'm looking for someone to travel down to her farm to see if everything's all right.\n\nIf you follow the road south out of the village, then into the swamp's interior, you'll find her farm near the middle of the Quagmire.", sourceObjective = "Speak to Tabetha at her farm in the Quagmire.", completion = "It's fortunate Nazeer thought to send someone. We've got some new neighbors and they've been nothing but pests since they set up camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[11214] = { id = 11214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission to Mudsprocket", description = "The Steamwheedle Cartel has recently established a new outpost in the southern part of Dustwallow Marsh. It's called Mudsprocket, if I recall, and it's located on the main road south out of Tabetha's Farm and the Stonemaul Ruins.\n\nThis is an excellent opportunity for us to establish new trade contacts and Lady Jaina wants me to send a representative down there to establish contact. Would you be willing to go?", sourceObjective = "Speak with Drazzit Dripvalve at Mudsprocket.", completion = "So Theramore is interested in doing business? Well, that's not an offer I'd turn down. Supplies are pretty scarce here right now, so we need all the business contacts we can get!", sourceObjectiveStatus = "unverified-source-field" }
quests[11215] = { id = 11215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Mudsprocket", description = "The Steamwheedle Cartel's new outpost in the southern part of the marsh isn't faring so well. The zeppelin carrying supplies to Mudsprocket crashed, leaving them without vital tools, food, and medical supplies.\n\nFollow the road down south and into the marsh's interior. You'll pass by Tabetha's Farm and the Stonemaul Ruins before the road brings you to Mudsprocket. Offer any help you can provide to the town's leadership.", sourceObjective = "Speak with Drazzit Dripvalve at Mudsprocket.", completion = "I won't turn down any help! We're in the process of setting up here and trying to make the most of what we've got, until those supplies from the zeppelin arrive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11216] = { id = 11216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archmage Alturus", description = "I was sent here by my mentor to look for assistance, but unfortunately I'm not allowed outside of Lower City and the individuals that frequent this establishment tend to be less than helpful.\n\nYou do seem different, more like the adventurous type.  If you're interested in aiding our cause, speak to Archmagae Alturus outside of Medivh's old dwelling, Karazhan.\n\nIn the meantime, I'm going to see about gaining access to the rest of the city.  One of our old associates is rumored to be here.", sourceObjective = "Speak to Archmage Alturus outside of Karazhan in Deadwind Pass.", completion = "I thank you for taking the time to come to our aid.  We've important work ahead of us.", sourceObjectiveStatus = "unverified-source-field" }
quests[11217] = { id = 11217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch a Dragon by the Tail", description = "With the zeppelin crash delaying supplies, we've run out of medicines and bandages.\n\nWe're making use of what we can, but between all the insects, the injuries, and the enemies we're encountering here, I can barely keep up! I've found one herb that seems to help heal wounds and dull pain, but it, too, is in short supply.\n\nIt's called wyrmtail, and it's abundant in the Dragonmurk and Wyrmbog areas east of town. The plants themselves are made of coiled stalks, and seem to pulsate when you look at them.", sourceObjective = "Gizzix Grimegurgle at Mudsprocket wants you to bring him 8 Wyrmtail stalks.", progress = "Did you find any of the wyrmtail?", completion = "Thank you! This will help keep our guys going out in the field until Moxie returns with the rest of the supplies from the zeppelin crash.", sourceObjectiveStatus = "unverified-source-field" }
quests[11219] = { id = 11219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Fires!", description = "The Horde's children need you, {name}.  The Headless Horseman, once a human paladin and now an insane fiend, has set fire to our village!  You must put out those fires!\n\nGrab a bucket and throw it onto the blaze, or toss it to an ally who is closer to the flames.  Extinguish all the fires and thwart the Headless Horseman!", sourceObjective = "The Masked Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Masked Orphan Matron in town.", progress = "The Horde's children need you!  Do not abandon them!", completion = "The fires are out!  You and your fire brigade were victorious!  Hah!\n\nThe Headless Horseman's attack has failed, but until he and his head are destroyed together, he will return.\n\nUntil then, however, let's take comfort in the safety you brought our children.  I am honored to have watched your brave work today.", sourceObjectiveStatus = "unverified-source-field" }
quests[11220] = { id = 11220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Headless Horseman", description = "Until the head of the Headless Horseman is destroyed, his rampage will not end.\n\nThe Horseman rests within the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glade.  Go to his pumpkin shrine and speak these words:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nThis will rouse the fiend.  Destroy the head of the Horseman's and he will plague us no longer.", sourceObjective = "Find the Headless Horseman's Pumpkin Shrine.", completion = "The origin of this shrine is unknown, but there is no doubt to whom it pays homage...", sourceObjectiveStatus = "unverified-source-field" }
quests[11222] = { id = 11222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn Bolvar!", description = "Although we don't have all the answers we might like, it's imperative that you bring our findings to Highlord Bolvar Fordragon right away!\n\nHe needs to know that the Defias have a powerful patron in Stormwind and that they're involved in the disappearance of King Varian!\n\nI can use my magic to expedite your trip to Stormwind. Just speak to me when you're prepared to go, {name}.", sourceObjective = "Speak to Highlord Bolvar Fordragon in Stormwind Keep.", completion = "<Highlord Bolvar listens while you deliver Jaina's message.>\n\nAre you certain? This is a very serious charge...", sourceObjectiveStatus = "unverified-source-field" }
quests[11223] = { id = 11223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Jaina", description = "Do not let Lady Prestor's protestations distract you, {name}. That she is blind to this problem does not surprise me, but that is a separate matter.\n\nAs I was saying, you and Lady Jaina have my thanks for bringing your findings to me in such haste. Let her know that no good citizen of Stormwind will rest until our king walks among us again.\n\nGo to the Mage Quarter at the western end of the city and speak with Archmage Malin at the foot of the tower there. He will speed your return to Theramore.", sourceObjective = "Speak to Lady Jaina Proudmoore in Theramore.", completion = "That is excellent news, {name}! I was worried the highlord might question the veracity of our information, but I see now my concern was misplaced.\n\nYou are to be well rewarded for your efforts on behalf of Theramore and the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[11225] = { id = 11225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit of Witch Hill", description = "The marsh seems to have a strange effect on humans. Some grow mad simply by living here.\n\nAnyone who has ever settled at Swamplight Manor has gone mad in a spectacular way. The latest owner, one \"Swamp Eye\" Jarl, is already showing signs.\n\nI don't completely understand what's happening there, you'd have my thanks for looking into it.\n\nThe manor is at the eastern edge of the swamp. Trek east across Bluefen and past North Point Tower. The manor is in a haunted patch of land called Witch Hill.", sourceObjective = "Speak with \"Swamp Eye\" Jarl at Swamplight Manor.", completion = "Have you come here to spy on me? No?\n\nPerhaps you have an appreciation for fine cuisine, then? Good, you can help!", sourceObjectiveStatus = "unverified-source-field" }
quests[11242] = { id = 11242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free at Last!", description = "Rage was my prison, {name}, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children may know that I will haunt them no more.", sourceObjective = "Take the Tome of Thomas Thomson to the Costumed Orphan Matron in Goldshire, Kharanos or Azure Watch.", progress = "You have something for me, good {name}?", completion = "What is this?  The tome of Thomas Thomson?  But that is the name of the Horseman before he was cursed!  Does this mean that he is finally free?  Does this mean he will no longer torment the good people of Azeroth?\n\nWhat a joyous day!  {name}, your feat will live long with us.  The children, and their children, will sing your name!", sourceObjectiveStatus = "unverified-source-field" }
quests[11293] = { id = 11293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for the Barleybrews!", description = "We need to get the word out about the Barleybrews at Brewfest.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.  I'll make things easy though, I'll lend you some racing ram reins and a racing ram for 4 minutes.  Use the reins to let him go, but try not to tire him out.", sourceObjective = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.", progress = "Have you finished spreading the word about Brewfest?  But more importantly, did you let people know about the Barleybrews?", completion = "Well done!  That kinda shouting is sure to bring business our way.\n\nAnd we promised you a reward, here it is.  The Barleybrews keep their word.\n\nOh, and come back any other day if you want to help spread the good name of Barleybrew.", sourceObjectiveStatus = "unverified-source-field" }
quests[11294] = { id = 11294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for the Thunderbrews!", description = "It's time to let people know that the Thunderbrew have heard their cries for good brew.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.\n\nWe'll make it easy though.  We'll lend you a ram AND some reins for 4 minutes.\n\nBe careful with going too fast though since you won't find any apple crates in Ironforge...  We can't take the chance of helping out the Barleybrew messengers.", sourceObjective = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.", progress = "Did you let everyone know that the Thunderbrews are here at Brewfest?", completion = "Good job!  That'll show those arrogant Barleybrews.\n\nWell we promised you a reward and here it is.  We Thunderbrew reward you with prizes, the Barleybrew reward you with foul odors and false promises.\n\nYou chose wisely.\n\nIf you want to keep making the right choice, stop by another day and help us spread the word.", sourceObjectiveStatus = "unverified-source-field" }
quests[11318] = { id = 11318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now This is Ram Racing... Almost.", description = "So you want to check out the racing rams?  Well I hope you're ready for speed.  BUT before I let you loose in the world, you'll need to show me that you can handle these fine creatures.\n\nSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.  If you need instructions how to handle the ram, talk to my apprentice, Pol Amberstill.", sourceObjective = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", progress = "Were you able to handle the speed?", completion = "Nice work there!  It takes time to get the hang of controlling your ram.  But once you do, you'll wish every ram was a racing ram.\n\nWhat's that? \"Where's my reward?\"  Ha Ha Ha... you got to ride the fastest ram around!  You want more?  Well how about this...\n\nYou've been rewarded with the chance to help other people around Brewfest.  There's plenty of work, and rewards, for an eager, young, ram racer.", sourceObjectiveStatus = "unverified-source-field" }
quests[11321] = { id = 11321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Did Someone Say \"Souvenir?\"", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", sourceObjective = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[11334] = { id = 11334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Shoots, He Scores!" }
quests[11335] = { id = 11335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, {name}.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", sourceObjective = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "Excellent news, {class}!  If our tactical deployments continue to be this successful, the Horde will be in full retreat before long.", sourceObjectiveStatus = "unverified-source-field" }
quests[11336] = { id = 11336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, {name}, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!", sourceObjective = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "Just what I wanted to hear!  A victory in Alterac Valley - even a temporary one - is crucial to our overall strategy against the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11337] = { id = 11337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm", description = "The fight against the Horde knows no boundaries, {name}.  Even in Outland, territorial disputes and old hatreds are enough to tip the scales in favor of war.\n\nGo into the Eye of the Storm and make sure the Alliance prevails in Outland just like it has in Azeroth.", sourceObjective = "Win an Eye of the Storm battleground match and return to an Alliance Brigadier General at any Alliance capital city or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "We've come one step closer to achieving total victory over the Horde.  We cannot allow the enemy to obtain a foothold in this world or any other.", sourceObjectiveStatus = "unverified-source-field" }
quests[11338] = { id = 11338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", sourceObjective = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city or Shattrath.", progress = "What news do you bring from the front, {name}?", completion = "Excellent work, {name}.  The integrity of our borders must be preserved at all costs!", sourceObjectiveStatus = "unverified-source-field" }
quests[11339] = { id = 11339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", sourceObjective = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city or Shattrath.", progress = "You're back already.  Do you bring news of victory?", completion = "You've brought great honor to the Horde, {name}.  Your victory today will ensure a thousand victories tomorrow!", sourceObjectiveStatus = "unverified-source-field" }
quests[11340] = { id = 11340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, {name}.  Earn great honor by heeding the call of the brave Frostwolf warriors.", sourceObjective = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "There is no greater honor than driving invaders from Horde territories.  We salute your great courage in aiding our forces today!", sourceObjectiveStatus = "unverified-source-field" }
quests[11341] = { id = 11341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm", description = "We will fight and crush the enemy wherever we find them.  Azeroth, Outland, the place makes no difference.\n\nWe cannot allow the Alliance to establish superiority in the Eye of the Storm.  Take the battle to them today... tomorrow it might be too late!", sourceObjective = "Win an Eye of the Storm battleground match and return to a Horde Warbringer at any Horde capital city or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "You bring honor to us all, {name}.  We must show the enemy that we will fight them wherever we find them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11342] = { id = 11342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", sourceObjective = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "The Horde is in your debt, {name}.  You've made your people proud with your courage in defending our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[11345] = { id = 11345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prizes for Pellets" }
quests[11354] = { id = 11354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Nazan's Riding Crop", description = "Today I have a buyer who is interested in a piece that's held by the mount of Illidan's herald. I, of course, speak of Vazruden the Herald and his dragon mount, Nazan.\n\nIf you want the finder's fee that I offer in return, find them flying above the Ramparts at Hellfire Citadel and return with the dragon's riding crop.\n\nMy sources tell me that the item in question is personally held by the dragon. It is said that Nazan refuses to allow Vazruden to strike him with it.", sourceObjective = "Wind Trader Zhareem has asked you to obtain Nazan's Riding Crop. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "The riding crop please.", completion = "Another soon-to-be satisfied customer. It looks like it's in fine condition. You are to be rewarded.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11356] = { id = 11356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Costumed Orphan Matron", description = "During Hallow's End, human orphanages have organized trips for their orphans to visit Alliance countryside villages.  Those poor children would love to see a real {class} like yourself!\n\nWhy don't you visit them?  You'll find orphans at Goldshire in Elwynn Forest, Kharanos in Dun Morogh and Azure Watch in Azuremyst.  Speak to the children's ward, a costumed orphan matron, and she'll introduce you to the children.", sourceObjective = "Speak with a Costumed Orphan Matron in either Goldshire, Kharanos or Azure Watch.", completion = "You're here to visit the children!  Wonderful!  They have known such heartache in their short lives.  It is good that they see real heroes like you.  It really lifts their spirits!", sourceObjectiveStatus = "unverified-source-field" }
quests[11357] = { id = 11357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masked Orphan Matron", description = "For Hallow's End, orc orphans were taken on a trip to many Horde villages.  The orphan matrons thought it would be good for them to see real heroes adventuring in the field.\n\nWhy don't you visit them?  A brave {class} like yourself could strengthen their spirits with tales of your valor!  Go to either Razor Hill in Durotar, Brill in Tirisfal Glades or Falconwing Square in Eversong Woods.  Speak with the masked orphan matron and she'll introduce you to the children.", sourceObjective = "Speak with a Masked Orphan Matron in either Razor Hill, Brill or Falconwing Square.", completion = "The children love to watch heroes at their work.  It is my hope that, one day, each of these orphans will grow into a strong member of the Horde, and ultimately die in glorious battle!\n\nAh, thoughts of such a fine fate brings mist to my eyes...", sourceObjectiveStatus = "unverified-source-field" }
quests[11360] = { id = 11360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Brigade Practice", description = "With the Headless Horseman at large, the heroes of Goldshire are always ready to form a fire brigade.  Do you want to help?\n\nNorth of here, guards set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here, or the one near the fires.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", sourceObjective = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", progress = "Hello, {name}.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the north!", completion = "You're wet and smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11361] = { id = 11361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Training", description = "The grunts set up a fire training area outside the village.  These days, Razor Hill's buildings often catch fire -- you should lend a hand and train as a fire fighter!\n\nHead west out of Razor Hill, then turn right as you pass the village's wall.  Find the training area, then grab buckets and toss them on the practice fires.", sourceObjective = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Razor Hill.", progress = "Have you dowsed any fires, {name}?  The training area is west of Razor Hill's western exit.", completion = "Well done, {name}!  Children, take a good look at this {class}. Grow strong and brave like him and one day you too will fight for the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11362] = { id = 11362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Keli'dan's Feathered Stave", description = "There is no accounting for taste. Take my most recent buyer for instance.\n\nThere is a blood orc within Hellfire Citadel known as Keli'dan the Breaker. He bears a most mundane stave; certainly nothing to take a second glance at. And yet, this is what my customer wishes.\n\nWho am I to say no?\n\nIf you desire my compensation, you will find him and his stave within the Blood Furnace.", sourceObjective = "Wind Trader Zhareem has asked you to obtain Keli'dan's Feathered Stave. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "We are speaking again... you must have the stave.", completion = "Perhaps I will have new feathers tied onto it before shipping it on to the buyer. I'm certain with so many arakkoa hereabouts it will not prove difficult. A small matter, and nothing to detract from your reward in any case.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11363] = { id = 11363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Bladefist's Seal", description = "Today I have a very wealthy collector in need of something very unique indeed.\n\nWarchief Kargath Bladefist carries upon his person his seal of command, which he uses to sign all official documents. I want you to retrieve it for me.\n\nYou will find him deep within the Shattered Halls. No doubt you will have to wade through a veritable army to get to him. I have no doubt that you will succeed.", sourceObjective = "Wind Trader Zhareem has asked you to obtain Bladefist's Seal. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I have heard it whispered that the warchief has weapons in place of his hands. Is this true?", completion = "Truly a daring acquisition that the bards should put pen to parchment for. Here, you have more than earned this.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11364] = { id = 11364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Shattered Hand Centurions", description = "Do you question your master? Neither does Mah'duun.\n\nThe blood of the centurions of the Shattered Hand clan is what I seek. You will find them within the Shattered Halls of Hellfire Citadel.\n\nIf you want the bounty, you will not return until you have slain them all.", sourceObjective = "Nether-Stalker Mah'duun has tasked you with the deaths of 4 Shattered Hand Centurions. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "You have returned. The centurions all lay dead?", completion = "Very well, you have earned your bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11368] = { id = 11368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Heart of Quagmirran", description = "I have an unusual request. A certain wealthy individual that I am in contact with off-world is interested in a macabre piece.\n\nSpecifically, she wants the heart of Quagmirran.\n\nI hear that the beast has three, but one will suffice for our purposes. As I understand it, you can find Quagmirran resting within a deep pool of water at the Slave Pens.", sourceObjective = "Wind Trader Zhareem has asked you to obtain The Heart of Quagmirran. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I trust that you know of a way to preserve the heart in transit?", completion = "Now that I think of it, it's a pity I didn't ask you to return with the other two hearts as well. Perhaps next time. In any case, you've earned your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11369] = { id = 11369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: A Black Stalker Egg", description = "There is only ever one great mother of the marsh walkers in Zangarmarsh. She is always known as the Black Stalker, and she hatches from one of the eggs left behind when her mother dies.\n\nI have a buyer who is interested in one of those eggs. He mentioned something about adding her as a zoo attraction.\n\nIf you are interested in the reward I am offering, travel to the Underbog and slay the Black Stalker for her egg.", sourceObjective = "Wind Trader Zhareem wants you to obtain a Black Stalker Egg. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "We're speaking again because you have the egg? Outstanding, let me see it!", completion = "Is it not amazing to feel the life pulsing within the egg? I must hurry to deliver it to the purchaser. We wouldn't want it hatching here now would we?\n\nYour payment is ready.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11370] = { id = 11370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Warlord's Treatise", description = "While it is known that Warlord Kalithresh of the naga is a great warrior in his own right, there are fewer who know that he has codified all of his knowledge.\n\nOne of my customers is aware of it though, and is keenly interested in obtaining his treatise.\n\nI ask that you travel to the Steamvault in Coilfang Reservoir and obtain this book for me.", sourceObjective = "Wind Trader Zhareem has asked you to acquire The Warlord's Treatise. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "My customer grows restless. I believe he wishes to plumb the depths of the warlord's tactical thinking to help with one of his ongoing conflicts.", completion = "Indeed, I fear my customer will not have time to peruse the entirety of this book. Nevertheless, that is not our concern.  Here is your reward.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11371] = { id = 11371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Coilfang Myrmidons", description = "Mah'duun hears and obeys, and I now ask you to be my instrument.\n\nIt has been related to me that the myrmidons of the coilfang tribe must be destroyed. Seek them out within the humid confines of the Steamvault underneath Coilfang Reservoir.\n\nI will accept nothing less than their utter annihilation.", sourceObjective = "Nether-Stalker Mah'duun has asked you to slay 14 Coilfang Myrmidons. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "How fares your fight against the coilfang myrmidons?", completion = "I trust that it was a fight worthy of your time? Certainly this bounty will be.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11372] = { id = 11372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Headfeathers of Ikiss", description = "I've recently been approached by a tauren whose husband is about to be elevated to chieftain. She wishes to make a special addition to his headdress.\n\nSpecifically, she wants to obtain the headfeathers from the dastardly Talon King Ikiss.\n\nIf you are interested in collecting my reward, travel to Auchindoun's Sethekk Halls and find him.", sourceObjective = "Wind Trader Zhareem has asked you to acquire The Headfeathers of Ikiss. Deliver them to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "The time of the chieftain's ceremony grows near.", completion = "I am sure that these feathers will make a fine addition to the chieftain's headdress. You have earned your compensation, {class}.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11373] = { id = 11373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Shaffar's Wondrous Pendant", description = "Today I have a personal request of you, yet the reward will certainly match the danger.\n\nMy family has a 'history', shall we say, with Nexus-Prince Shaffar and his followers. If the amulet he wears were to fall into my hands then surely that would mean that he had been dealt with.\n\nIf the bounty I am offering is of interest to you then journey to his lair within Auchindoun's Mana-Tombs.", sourceObjective = "Wind Trader Zhareem wants you to obtain Shaffar's Wondrous Amulet. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Not many know that the source of Shaffar's magic rests solely within his amulet. Without it he is powerless.\n\nThen again, if you have it that must mean that he is dead.", completion = "<You sense a deep level of satisfaction from the wind trader.>\n\nGood, I am glad to hear of his demise. And perhaps I will be able to unlock the secrets of his amulet for myself. If not, then I will sell it for a handsome price.\n\nI trust that this reward is sufficient.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11374] = { id = 11374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Exarch's Soul Gem", description = "Within Auchindoun's Auchenai Crypts many unsavory experiments are undertaken in the pursuit of a greater understanding of the necromantic arts. Many are the spirits that are tortured or destroyed therein.\n\nI have a customer who is interested in the liberation of one of those spirits. I have been informed that this spirit is contained within a soul gem held by none other than Exarch Maladaar himself.\n\nSeek him out within the crypts with all due haste and return to me with the gem.", sourceObjective = "Wind Trader Zhareem has asked you to recover The Exarch's Soul Gem. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Can you imagine being trapped within a gem for all eternity?", completion = "You're quite the hero, {name}. I am certain that my customer will find a way to free the spirit of their loved one from within the gem. For a job well done, your payment awaits.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11375] = { id = 11375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Murmur's Whisper", description = "When I'm done speaking, you may not want to take this commission.\n\nI have an eccentric client who specializes in the study of dead realities. It is rumored that the being known as Murmur destroyed the last world from which he was summoned. The professor is interested in examining his 'whisper' as he called it to understand how it is that Murmur accomplished such a feat.\n\nWill you journey to the Shadow Labyrinth within Auchindoun and retrieve it for me?", sourceObjective = "Wind Trader Zhareem has asked you to obtain Murmur's Whisper. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I'm not even certain what form a whisper is supposed to take in the physical world, but the professor assures me that you'll know it when you see it.\n\nPerhaps it is something akin to the being's voice box?", completion = "I was worried that you might not return. I trust that you didn't go deaf from fighting Murmur?\n\nHere is your reward. The professor will be pleased no doubt, though I worry what he ultimately wishes to do with this thing.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11376] = { id = 11376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Malicious Instructors", description = "Mah'duun has heard it said that none are as cruel as the six-armed demonesses inside the Shadow Labyrinth.\n\nGo to Auchindoun, seek them out, kill them all.\n\nIf you cannot accomplish so simple a task, we do not have anything further to say to one another.", sourceObjective = "Nether-Stalker Mah'duun wants you to kill 3 Malicious Instructors. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "The instructors, they are all dead? No?\n\nDid I not say not to return unless you had killed them all?", completion = "I am satisfied. He who speaks through the nether shall be as well. Mah'duun has your bounty prepared.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'deen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11377] = { id = 11377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge is Tasty", description = "I'm providing the catering for some unusual party guests tonight.  One of these fellows was flying around in Skettis and got knocked to the ground by a monstrous kaliri--his leg was broken badly.\n\nThey've requested something special for his get well party: Kaliri Stew.\n\nI can loan you my cooking pot so you can whip up a batch of stew for me.  The recipe itself is simple, but you'll need to get a giant kaliri wing and some cooked warp burgers.", sourceObjective = "The Rokk in Lower City has asked you to cook up some Kaliri Stew using his cooking pot. Return to him when it's done.", progress = "Do I smell something tasty?", completion = "Oh, I do smell something tasty!  I hope you gave that bird quite a good beating.\n\nPlease, help yourself to some of my extra stock.  I'm sure someone of your talent could put it to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[11378] = { id = 11378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Epoch Hunter's Head", description = "The tastes of my customers range from the mundane to the exotic. And sometimes they want to do very mundane things with the exotic objects they seek.\n\nSuch is the case with my latest request. My client, who shall remain nameless, wishes to obtain the head of the Epoch Hunter to mount on his wall.\n\n{class}, will you find a way to travel back in time to Old Hillsbrad and procure said head for my trophy-hunting patron?", sourceObjective = "Wind Trader Zhareem has asked you to obtain the Epoch Hunter's Head. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "The head of the Epoch Hunter... how does one come to the decision that they want it mounted on their wall?\n\nAnd even then, to not hunt the beast yourself, what does one say to their friends when asked how the fight went?\n\nHe'll lie, I suppose.", completion = "I see you are returned to the present time intact.\n\n<The wind trader looks around.>\n\nIt doesn't appear that anything has changed. But then again, how would I know?\n\nThat's a nice cut; my customer will be pleased. Here is your reward.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11379] = { id = 11379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Hot Stew", description = "I'm trying to invent something with some real zing.  But to be honest, I'm more of an idea goblin these days.  I've lost my sense of adventure.\n\nBut you... remind me of my younger days; ready to take on the world with a sword in one hand and a skillet in the other.\n\nI want you to take my beloved cooking pot and head out to Blade's Edge.  Throw in some shortribs and crunchy serpent--already cooked for extra flavor--and broil it over an abyssal's corpse, the only thing hot enough to do the trick.", sourceObjective = "The Rokk in Lower City has asked you to cook up some Demon Broiled Surprise using his cooking pot, two Mok'Nathal Shortribs and a Crunchy Serpent. Return to him when it's done.", progress = "Any luck with my little experiment?", completion = "Now look at that...\n\n<The Rokk takes a sip of the concoction and his face twists into a bizarre mask of pain and delight.>\n\nSweet A'dal that's good!  A cook with your potential shouldn't be without his proper materials.  Take some of my extra stock and make me proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[11380] = { id = 11380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manalicious", description = "Wouldn't you know it, I think my foodstuffs are up to date and someone comes along and requests the unusual: Mana Berry Delight.\n\nUnfortunately, mana berries are only found in the eco-domes of Netherstorm.  Just don't bother looking around Stormspire--it's picked clean.\n\nI could only trust someone trained in the culinary arts to pick the best berries, so don't let me down!", sourceObjective = "The Rokk in Lower City has asked you collect 15 Mana Berries from the Eco-Domes in Netherstorm.", progress = "Any luck, friend?", completion = "Those are the juiciest mana berries I've ever seen.  I think I'm getting smarter just by looking at them.\n\nSince I no longer need most of my meat and fish stock, why don't you take some?  I'm certain you could make something delicious.", sourceObjectiveStatus = "unverified-source-field" }
quests[11381] = { id = 11381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soup for the Soul", description = "Death is in the air.  I've never had so many orders for my famous soup--it lifts your spirits and soothes the soul.\n\nAnd I know a fellow cook when I see one!  Would you like to help me out and get a cut of the profits?\n\nHere, take my cooking pot, gather some clefthoof meat and I'll let you in on a little secret.  What makes my soup so good for the soul?  It's not chicken--I cook it at the Ancestral Grounds in Nagrand to soak up all that spiritual stuff there.", sourceObjective = "The Rokk in Lower City has asked you to cook up some Spiritual Soup using his cooking pot. Return to him when it's done.", progress = "What smells so good?", completion = "That is a fine batch of spiritual soup if I ever did smell one.  Just a pinch of pepper and it's done.\n\nAs promised, here's your cut.  And because you did such a fine job, I'm going to throw in some of my extra stock.", sourceObjectiveStatus = "unverified-source-field" }
quests[11382] = { id = 11382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Aeonus's Hourglass", description = "I swear that some of my customers are crazy. There are possessions that you go after, and there are ones that you dare not even think of!\n\nMy current client is clearly over-the-top insane. He covets the hourglass that Aeonus holds.\n\nYes, you heard right, Aeonus of the Infinite Dragonflight!\n\nWho am I to argue since he's paying a king's ransom? So, ready to go to the Caverns of Time and travel to the Black Morass to retrieve it for me?", sourceObjective = "Wind Trader Zhareem has asked you to acquire Aeonus's Hourglass. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "If I were you, I would be very careful with time-travel. You wouldn't want to accidentally do something, like kill one of your ancestors, and then accidentally erase yourself from the present!", completion = "Odd that the sands in that thing are still falling upward. I think I will have it delivered to its new owner with all due haste.\n\nI thank you for a job well done, {class}. You have certainly earned your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11383] = { id = 11383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Rift Lords", description = "Mah'duun knows where you must go. Mah'duun knows that you must kill rift lords. But, Mah'duun does not know exactly when.\n\nI know that does not make sense, but the voice on the winds was not more specific.\n\nTravel to the Black Morass through the Caverns of Time and the way shall be made clear.", sourceObjective = "Nether-Stalker Mah'duun wants you to kill 4 Rift Lords. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "We are speaking, but I sense that all of the rift lords are not yet dead.\n\nReturn again when they are, {class}.", completion = "You found your way back in time, and then back again. You must be a great {class}, {race}. The bounty is earned.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11384] = { id = 11384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: A Warp Splinter Clipping", description = "Not long ago, I was approached by a kaldorei druidess with a touching request. And plenty of gold, of course!\n\nIt would appear that the forces of Darnassus wish to restore an ancient of the arcane known as Warp Splinter. The giant tree has been confused or corrupted, I'm not certain, but you'll find it inside of the Botanica at Tempest Keep.\n\nShe said that all they would need to regrow him was a small clipping.", sourceObjective = "Wind Trader Zhareem has asked you to obtain a Warp Splinter Clipping. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Did you lose your way to the Botanica? You can't miss it... it's at Tempest Keep off of the eastern edge of the Netherstorm.", completion = "Aw, you did get it! It's so tiny. And yet, when the druids are done with it -- a process I am told will take a very long time -- Warp Splinter will be regrown anew.\n\nAnd here is your reward as promised.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11385] = { id = 11385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Sunseeker Channelers", description = "It has been whispered to Mah'duun that the channelers of the military unit known as the Sunseekers must be killed today.\n\nThey are to be found within the Botanica at Tempest Keep.\n\nYou want the bounty, you kill the channelers.", sourceObjective = "Nether-Stalker Mah'duun wants you to kill 6 Sunseeker Channelers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "How can it be that we are speaking when the channelers are not all lying dead?", completion = "And now they are dead, channeling no longer. He who whispers upon the nether is satisfied and you have secured the bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11386] = { id = 11386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Pathaleon's Projector", description = "I always assumed that Pathaleon the Calculator used magic to project his image across Outland. Apparently I was wrong.\n\nMy latest customer tells me that the blood elf uses a mechanical device for his communication with the leaders of Prince Kael'thas's special projects. As I understand it, he acquired it from the Zaxxis rebels in the Netherstorm.\n\nMy client wishes to obtain the projector. Why don't you pay Pathaleon a visit? He can be found within the Mechanar at Tempest Keep.", sourceObjective = "Wind Trader Zhareem has asked you to acquire Pathaleon's Projector. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "It's not that projector technology is something special in and of itself, but the range of this particular model is a true breakthrough!", completion = "I'm tempted to keep it for myself and return my client's money. It could certainly expand the reach of my business.\n\n<The wind trader sighs.>\n\nHowever, I have a reputation to uphold.\n\nSpeaking of my reputation, thank you for helping me to maintain it. Here is your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11387] = { id = 11387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Tempest-Forge Destroyers", description = "There are mechanical constructs within the Mechanar which Mah'duun has been told must be dismantled.\n\nGo to Tempest Keep, find the tempest-forge destroyers and destroy them.\n\nThen you may return to collect the bounty.", sourceObjective = "Nether-Stalker Mah'duun wants you to destroy 5 Tempest-Forge Destroyers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", completion = "Mah'duun enjoys fighting constructs; they are less messy than organic beings.\n\nThe bounty is yours.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11388] = { id = 11388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Scroll of Skyriss", description = "Today's client seeks something truly unique.\n\nIt is said that Harbinger Skyriss is a servant of the Old Gods. It is also said that he carries a large scroll that contains their instructions for his domination of life in the universe on their behalf.\n\nMy current buyer wishes to get <his/her> hands on that scroll, nevermind that <he/she> won't be able to read the language upon it.\n\nTravel to Tempest Keep's Arcatraz and get it for me, will you, {class}?", sourceObjective = "Wind Trader Zhareem has asked you to obtain The Scroll of Skyriss. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "It must be a very dangerous thing to do to meddle directly in the affairs of the Old Gods.\n\nBetter you than me!", completion = "I dare not touch the scroll lest I too risk the notice of the Old Gods. I will have one of my assistants handle its delivery.\n\nYou have more than earned your reward, {class}, and I wish you all the luck in the known worlds.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11389] = { id = 11389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Arcatraz Sentinels", description = "The sentinels within the Arcatraz have gone haywire. The prisoners run rampant and the guards attack those that would help.\n\nMah'duun hears the speaker on the nether winds. The speaker says to destroy the sentinels\n\nAccomplish this and today's bounty is yours.", sourceObjective = "Nether-Stalker Mah'duun wants you to dismantle 5 Arcatraz Sentinels. Return to him in Shattrath's Lower City once that has been accomplished in order to collect the bounty.", completion = "With the sentinels destroyed, perhaps the naaru will ask the Consortium to replace them? Mah'duun does not know and does not care.\n\nYou have earned the bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11392] = { id = 11392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine.", sourceObjective = "Take a Dreary Candle to the Loosely Turned Soil.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[11400] = { id = 11400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest Riding Rams", description = "If you show this hand stamp to Pol Amberstill, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", sourceObjective = "Bring the \"Honorary Brewer\" Hand Stamp to Pol Amberstill near the entrance to the Brewfest Grounds in Dun Morogh.", progress = "Is that an \"Honorary Brewer\" stamp you've got on your hand?", completion = "Good job, {name}... you've won the trust of the festival's brewers, earning the right to purchase a Brewfest riding ram.", sourceObjectiveStatus = "unverified-source-field" }
quests[11401] = { id = 11401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", sourceObjective = "Take a Dreary Candle to the Loosely Turned Soil.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[11403] = { id = 11403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free at Last!", description = "Rage was my prison, {name}, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children will know that I will haunt them no more.", sourceObjective = "Take the Tome of Thomas Thomson to a Masked Orphan Matron in Durotar, Brill or Falconwing Square.", progress = "{name}, it is good to see you again.  I'm sure the children enjoy tales of your heroism.", completion = "What?  This holy tome once belonged to an infamous paladin of the Alliance.  Was he the Headless Horseman?  Does this mean that the Horseman is defeated?\n\nThis is a glorious day, {name}!  Your legend will shine bright, and may it last for twice the years of the Horseman's reign of fear.", sourceObjectiveStatus = "unverified-source-field" }
quests[11404] = { id = 11404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", sourceObjective = "Take a Dreary Candle to the Loosely Turned Soil.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[11405] = { id = 11405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", sourceObjective = "Take a Dreary Candle to the Loosely Turned Soil.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[11407] = { id = 11407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for Drohn's Distillery!", description = "So, do you want to help bring strength and honor to Brewfest?  We need you to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nWe'll lend you a racing ram for 4 minutes and also give you these racing reins.\n\nBe careful though, the cheap goblins didn't put any apple crates along the way.", sourceObjective = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.", progress = "Have you finished spreading the word about Brewfest?", completion = "You kept your word and let people know about our brewmasters.  Thank you. We promised you these tokens, and gladly give them to you.  I imagine the trolls are a bit more stingy with handing over their tokens...\n\nCome back another day to help us spread the word about Brewfest.", sourceObjectiveStatus = "unverified-source-field" }
quests[11408] = { id = 11408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for T'chali's Voodoo Brewery!", description = "We need to spread the word about the trolls at Brewfest.  Ya need to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nBut I'll make it easy for ya, I'll lend you a racing ram for 4 minutes.  I'll also give you these racing reins.\n\nBe careful though, the goblins didn't put any apple crates along the way.  They are cheap like that.", sourceObjective = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.", progress = "Have you finished spreading the word about Brewfest?  But more importantly, did you let people know about the amazing troll brew?", completion = "Ya did it!  We gotta get ready for the flood of customers that are sure to come our way!  Thanks!\n\nOh, that's right, and we promised you a reward.  Can't forget about that...\n\nFeel free to stop by again another day to help us spread the word some more.", sourceObjectiveStatus = "unverified-source-field" }
quests[11409] = { id = 11409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now This is Ram Racing... Almost.", description = "So you want to check out the racing rams?  The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?\n\nNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.\n\nSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.", sourceObjective = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", completion = "Hey, that wasn't too bad... are you sure you're not a dwarf?\n\nSo there's plenty more racing to be had and it's not just from me.  All over the Brewfest grounds you'll find people in need of a decent ram racer.  So go and make yourself useful.\n\nOh and don't forget, these rams were legally obtained.  I just want to make sure we're clear.", sourceObjectiveStatus = "unverified-source-field" }
quests[11412] = { id = 11412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There and Back Again", description = "Am I glad you're here.  We are in big trouble!  The goblin that was supposed to be bringing us more brew had an accident on his way from Razor Hill.  You gotta get us that brew!\n\nI'll put you on one of my racing rams and you follow the road to Razor Hill.\n\nOnce you get near him he'll toss you a keg, then you run the keg back here and toss the keg to my more capable assistant.  For now, all we want are 3 kegs.  Do a good job and maybe we'll have another job for you.", sourceObjective = "Get a keg from the Goblin stranded on the road to Razor Hill and return it to Ram Master Ray's assistant. Do this 3 times before your ram goes away.", progress = "Did you see the mess that goblin made?  I hope you didn't do too much reckless off-roading.", completion = "Thanks for your help!  As long as Brewfest is going, the Dark Iron dwarves are attacking and our supplier is stuck in that canyon, I'll need some help shipping kegs.  So if you want to work for more tokens, talk to me every day.\n\nHere are the tokens we promised you.  Have fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[11413] = { id = 11413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Did Someone Say \"Souvenir?\"", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", sourceObjective = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[11419] = { id = 11419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest Riding Rams", description = "If you show this hand stamp to Driz Tumblequick, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", sourceObjective = "Bring the \"Honorary Brewer\" Hand Stamp to Driz Tumblequick near the entrance to the Brewfest Grounds in Durotar.", progress = "Is that an \"Honorary Brewer\" stamp you've got on your hand?", completion = "Good job, {name}... you've won the trust of the festival's brewers, earning the right to purchase a Brewfest riding ram.", sourceObjectiveStatus = "unverified-source-field" }
quests[11431] = { id = 11431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch the Wild Wolpertinger!", description = "Hey there!  I'm a crazy dwarf!  We dwarves believe when you get enough brew together, invisible creatures show up.  In fact they are probably wandering around the Brewfest grounds right now! But you can only see them if you are really drunk.\n\nWe dwarves will come up with any excuse to drink.\n\nI bet you want a reason to drink too...  So here it is, bring me 5 of those wolpertingers with this net I got from a really drunk dwarf.\n\nIf you can't see them, you're probably not drunk enough.", sourceObjective = "The \"dwarf,\" Glodrak Huntsniper, has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. He mentioned that you must be intoxicated to see them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11439] = { id = 11439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Brigade Practice", description = "The brave dwarves of Kharanos can form a fire brigade in an instant, now that the Headless Horseman is around. Do you want to help?\n\nSouth of here, the mountaineers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", sourceObjective = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", progress = "Hello, {name}.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the south!", completion = "You're smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11440] = { id = 11440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Brigade Practice", description = "With the threat of the Headless Horseman looming, the peacekeepers have been diligent in forming a fire brigade when needed. Do you want to help?\n\nWest of here, toward the Exodar, the peacekeepers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", sourceObjective = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", progress = "Hello, {name}.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the west!", completion = "You're wet and smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11441] = { id = 11441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest!", description = "Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", sourceObjective = "Speak to the Brewfest Organizer.", completion = "Ho ho! Come for your free beer?", sourceObjectiveStatus = "unverified-source-field" }
quests[11442] = { id = 11442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Brewfest!", completion = "Ho ho! Come for your free beer?" }
quests[11446] = { id = 11446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest!", description = "Speak to the Brewfest Organizer at the Brewfest Grounds outside of Orgrimmar and receive a free beer.", sourceObjective = "Speak to the Brewfest Organizer.", completion = "What?! A free beer? Yeah, yeah. I guess we said we'd do that this year.", sourceObjectiveStatus = "unverified-source-field" }
quests[11447] = { id = 11447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Brewfest!", completion = "What?! A free beer? Yeah, yeah. I guess we said we'd do that this year." }
quests[11449] = { id = 11449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Training", description = "The deathstalkers have set up a fire training area outside the town.  We cannot afford further damage to the buildings of Brill - you should do your duty and train as a fire fighter.\n\nHead west past the graveyard, following the road. You'll find the training area there.", sourceObjective = "Toss buckets on 5 fires, then speak with the Masked Orphan Matron in Brill.", progress = "Have you dowsed any fires, {name}?  The training area is west of Brill.", completion = "Well done, {name}.  Children, take a good look at this {class}.  Let him be a strong example to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11450] = { id = 11450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Training", description = "The guards have set up a fire training area outside the town.  We cannot allow the Horseman to destroy what we have worked so hard to rebuild - you should do your duty and train as a fire fighter.\n\nHead south through the gate to the crossroads. You'll find the training area there.", sourceObjective = "Toss buckets on 5 fires, then speak with the Masked Orphan Matron in Falconwing Square.", completion = "Well done, {name}.  Children, take a good look at this {class}.  Let him be a fine example for you to follow.", sourceObjectiveStatus = "unverified-source-field" }
quests[11451] = { id = 11451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alicia's Poem", description = "Hi, I wrote a poem for my friend Caylee.  She likes to hang out with the Aldor in Shattrath City.  You know, in Outland?\n\nCould you take my poem to her?  My mommy says I'm too young to go to Shattrath City!", sourceObjective = "You have been asked to deliver Alicia's Poem to Caylee Dak in Shattrath City in Outland.", progress = "Oh, is that a poem?", completion = "What a touching poem, thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11454] = { id = 11454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Saboteurs", description = "This scrap of paper seems to have been left behind accidentally by the Dark Iron invaders.\n\nWhile the plans are complicated and written in some form of coded Dwarvish, the signature at the end - \"Coren Direbrew\" - is clear enough, as is mention of the Grim Guzzler deep within Blackrock Depths. You should seek out the instigator and put an end to these raids.", sourceObjective = "Find Coren Direbrew in the Grim Guzzler within Blackrock Depths.", sourceObjectiveStatus = "unverified-source-field" }
quests[11481] = { id = 11481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crisis at the Sunwell", description = "By the naaru, I thank you, {race}, for your efforts.\n\nOur work is far from finished, however, and I must request that you undertake a critical mission - one as important as any I've issued.\n\nOur forces are spread thinly. To compound the strain, we've had to dispatch a contingent to Azeroth to investigate developments at the Sunwell Plateau.\n\nYou are needed there, {name}. Report to Larethor. Tell him that I wish we could spare more men.", sourceObjective = "Adyen the Lightwarden on the Aldor Rise in Shattrath City has requested that you travel to Sunwell Plateau and speak with Larethor.", completion = "Another soldier from Shattrath? A welcome sight!\n\nWish there were more of you, but we'll make due with what we have. Whatever's going on out here won't wait for us to make ready.\n\nHave a look around, {class}. There's much that needs doing. Pitch in and do your share.\n\nOh, yeah, and don't go tauntin' the cryers - err, Scryers. Looks like we're in this thing together....", sourceObjectiveStatus = "unverified-source-field" }
